def _glavapu_base_costs(rows: list[list[Any]]) -> dict[str, float]:
    """Ð‘Ð°Ð·Ð¾Ð²Ñ‹Ðµ ÑÑ‚Ð¾Ð¸Ð¼Ð¾ÑÑ‚Ð¸ Ð¿Ð¾ Ñ‚Ð¸Ð¿Ð°Ð¼ Ð¸ÑÐ¿Ð¾Ð»ÑŒÐ·Ð¾Ð²Ð°Ð½Ð¸Ñ Ð¸Ð· Ð»Ð¸ÑÑ‚Ð° Â«ÐŸÐ°Ñ€Ð°Ð¼ÐµÑ‚Ñ€Ñ‹ Ñ‚ÐµÑ€Ñ€Ð¸Ñ‚Ð¾Ñ€Ð¸Ð¸Â».

    Ð¢Ð°Ð±Ð»Ð¸Ñ†Ð° Ð¸Ð´Ñ‘Ñ‚ Ð¿Ð¾ÑÐ»Ðµ Ð·Ð°Ð³Ð¾Ð»Ð¾Ð²ÐºÐ° Â«Ð¢Ð¸Ð¿ Ð¸ÑÐ¿Ð¾Ð»ÑŒÐ·Ð¾Ð²Ð°Ð½Ð¸Ñ | Ð£ÐŸÐšÐ¡ | Ð‘Ð°Ð·Ð¾Ð²Ð°ÑÂ»: Ñ‚Ñ€ÐµÑ‚Ð¸Ð¹
    ÑÑ‚Ð¾Ð»Ð±ÐµÑ† â€” Ð±Ð°Ð·Ð¾Ð²Ð°Ñ ÑÑ‚Ð¾Ð¸Ð¼Ð¾ÑÑ‚ÑŒ, Ð²Ñ‚Ð¾Ñ€Ð¾Ð¹ â€” Ð£ÐŸÐšÐ¡. ÐÑƒÐ»ÐµÐ²Ð°Ñ Ð±Ð°Ð·Ð¾Ð²Ð°Ñ Ð¾Ð·Ð½Ð°Ñ‡Ð°ÐµÑ‚, Ñ‡Ñ‚Ð¾
    Ð·Ð° ÑÑ‚Ð¾Ñ‚ Ð²Ð¸Ð´ Ð½Ðµ Ð¿Ð»Ð°Ñ‚ÑÑ‚ (Ð¿Ñ€Ð¾Ð¸Ð·Ð²Ð¾Ð´ÑÑ‚Ð²Ð¾, ÑÐ¾Ñ†Ð¸Ð°Ð»ÑŒÐ½Ñ‹Ðµ Ð¾Ð±ÑŠÐµÐºÑ‚Ñ‹), Ð¸ Ð½Ð¾Ð»ÑŒ Ð·Ð´ÐµÑÑŒ
    Ð¾ÑÐ¼Ñ‹ÑÐ»ÐµÐ½Ð½Ñ‹Ð¹ â€” Ð¾Ð½ Ð¸ ÑÐ¾Ñ…Ñ€Ð°Ð½ÑÐµÑ‚ÑÑ.
    """
    found: dict[str, float] = {}
    for row in rows or []:
        name = str((row or [None])[0] or "").strip().lower()
        if not name or len(row) < 3:
            continue
        key = next((code for code, needle in _GLAVAPU_USE_ROWS if name.startswith(needle)), "")
        if not key:
            continue
        value = _ru_number(row[2])
        if value is None:
            continue
        found[key] = float(value)
    return found


def parse_glavapu_xlsx(data: bytes, filename: str = "") -> dict[str, Any]:
    tables = _xlsx_read_tables(data)
    tep_sheet = next((name for name in tables if name.strip().lower() == "Ñ‚ÑÐ¿"), None)
    if not tep_sheet:
        tep_sheet = next((name for name in tables if "Ñ‚ÑÐ¿" in name.lower()), None)
    if not tep_sheet:
        raise ValueError("ÐÐµ Ð½Ð°Ð¹Ð´ÐµÐ½ Ð»Ð¸ÑÑ‚ Â«Ð¢Ð­ÐŸÂ». ÐžÐ¶Ð¸Ð´Ð°ÐµÑ‚ÑÑ Ñ„Ð¾Ñ€Ð¼Ð°Ñ‚ ÐºÐ°Ð»ÑŒÐºÑƒÐ»ÑÑ‚Ð¾Ñ€Ð° Ð“Ð»Ð°Ð²ÐÐŸÐ£.")

    rows = tables[tep_sheet]
    by, all_rows = _row_map(rows)

    parking_sheet = next((name for name in tables if "Ð¼Ð°ÑˆÐ¸Ð½Ð¾" in name.lower()), None)
    params_sheet = next((name for name in tables if "Ð¿Ð°Ñ€Ð°Ð¼ÐµÑ‚Ñ€Ñ‹ Ñ‚ÐµÑ€Ñ€Ð¸Ñ‚Ð¾Ñ€Ð¸Ð¸" in name.lower()), None)
    params_rows = tables.get(params_sheet, []) if params_sheet else []

    # Source data. Ð¡ÐŸÐŸ/ÐÐŸ are stored in Ñ‚Ñ‹Ñ. ÐºÐ². Ð¼ and converted to mÂ².
