def _manual_tep_number(value: Any, field: str) -> float:
    if value is None or str(value).strip() == "":
        return 0.0
    number = _ru_number(value)
    if number is None:
        raise ValueError(f"ÐŸÐ¾Ð»Ðµ Â«{field}Â» Ð´Ð¾Ð»Ð¶Ð½Ð¾ ÑÐ¾Ð´ÐµÑ€Ð¶Ð°Ñ‚ÑŒ Ñ‡Ð¸ÑÐ»Ð¾")
    if number < 0:
        raise ValueError(f"ÐŸÐ¾Ð»Ðµ Â«{field}Â» Ð½Ðµ Ð¼Ð¾Ð¶ÐµÑ‚ Ð±Ñ‹Ñ‚ÑŒ Ð¾Ñ‚Ñ€Ð¸Ñ†Ð°Ñ‚ÐµÐ»ÑŒÐ½Ñ‹Ð¼")
    if number > 1_000_000_000:
        raise ValueError(f"ÐŸÐ¾Ð»Ðµ Â«{field}Â» ÑÐ¾Ð´ÐµÑ€Ð¶Ð¸Ñ‚ Ð½ÐµÑ€ÐµÐ°Ð»Ð¸ÑÑ‚Ð¸Ñ‡Ð½Ð¾ Ð±Ð¾Ð»ÑŒÑˆÐ¾Ðµ Ð·Ð½Ð°Ñ‡ÐµÐ½Ð¸Ðµ")
    return float(number)


