class ProjectPresetRequest(BaseModel):
    """ÐŸÑ€ÐµÑÐµÑ‚ Ð¸ Ñ‚Ð¾, Ñ‡Ñ‚Ð¾ ÑƒÐ¶Ðµ Ð¾Ñ‚ÐºÑ€Ñ‹Ñ‚Ð¾ Ð² Ð¿Ñ€Ð¾ÐµÐºÑ‚Ðµ, â€” Ñ‡Ñ‚Ð¾Ð±Ñ‹ Ð¿Ð¾ÐºÐ°Ð·Ð°Ñ‚ÑŒ Ñ€Ð°Ð·Ð½Ð¸Ñ†Ñƒ."""

    preset: dict[str, Any]
    mode: str = "preview"
    inputs: dict[str, Any] = {}
    tep: dict[str, dict[str, Any]] = {}
    # Ð§Ð¸ÑÐ»Ð°, Ð²Ð²ÐµÐ´Ñ‘Ð½Ð½Ñ‹Ðµ Ñ‡ÐµÐ»Ð¾Ð²ÐµÐºÐ¾Ð¼ Ð½Ð° ÑÐºÑ€Ð°Ð½Ðµ Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐºÐ¸ Ð²Ð·Ð°Ð¼ÐµÐ½ TBD. ÐŸÑ€Ð¸Ñ…Ð¾Ð´ÑÑ‚
    # Ð¾Ñ‚Ð´ÐµÐ»ÑŒÐ½Ð¾ Ð¾Ñ‚ Ð¿Ñ€ÐµÑÐµÑ‚Ð°: Ñ„Ð°Ð¹Ð» â€” Ð´Ð¾ÐºÑƒÐ¼ÐµÐ½Ñ‚, Ð° ÑÑ‚Ð¾ Ð´Ð¾Ð¿Ð¾Ð»Ð½ÐµÐ½Ð¸Ðµ Ðº Ð½ÐµÐ¼Ñƒ.
    filled: dict[str, Any] = {}


def _preset_diff(current: dict[str, Any], incoming: dict[str, Any],
                 labels: dict[str, str] | None = None) -> list[dict[str, Any]]:
    """Ð§Ñ‚Ð¾ Ð¸Ð¼ÐµÐ½Ð½Ð¾ Ð¸Ð·Ð¼ÐµÐ½Ð¸Ñ‚ÑÑ. Ð‘ÐµÐ· ÑÑ‚Ð¾Ð³Ð¾ Â«ÐŸÑ€Ð¸Ð¼ÐµÐ½Ð¸Ñ‚ÑŒÂ» â€” Ð¿Ñ€Ñ‹Ð¶Ð¾Ðº Ð² Ñ‚ÐµÐ¼Ð½Ð¾Ñ‚Ðµ."""
    rows: list[dict[str, Any]] = []
    for key, new_value in incoming.items():
        old_value = current.get(key)
        if isinstance(new_value, (int, float)) and isinstance(old_value, (int, float)):
            if abs(float(new_value) - float(old_value)) < 1e-6:
                continue
        elif old_value == new_value:
            continue
        rows.append({
            "key": key,
            "label": (labels or {}).get(key, key),
            "was": old_value,
            "becomes": new_value,
            "action": "Ð·Ð°Ð¼ÐµÐ½Ð¸Ñ‚ÑÑ" if old_value not in (None, "", 0, 0.0) else "Ð·Ð°Ð¿Ð¾Ð»Ð½Ð¸Ñ‚ÑÑ",
        })
    return rows


@app.get("/api/project-presets")
def list_project_presets(session: str = "", key: str = "") -> dict[str, Any]:
    """ÐŸÑ€ÐµÑÐµÑ‚Ñ‹ Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð¾Ð², Ð»ÐµÐ¶Ð°Ñ‰Ð¸Ðµ Ð½Ð° ÑÐµÑ€Ð²ÐµÑ€Ðµ.

    ÐŸÑ€ÐµÑÐµÑ‚ Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð° â€” Ð½Ðµ Ñ‚Ð¾ Ð¶Ðµ, Ñ‡Ñ‚Ð¾ Ð¿Ñ€ÐµÐ´ÑƒÑÑ‚Ð°Ð½Ð¾Ð²ÐºÐ° Ð¢Ð­ÐŸ: Ñ‚Ð¾Ñ‚ Ð½ÐµÑÑ‘Ñ‚ ÐºÐ½Ð¸Ð³Ñƒ Ñ
    Ð¿Ð»Ð¾Ñ‰Ð°Ð´ÑÐ¼Ð¸, ÑÑ‚Ð¾Ñ‚ â€” Ð²ÐµÑÑŒ Ð¿Ñ€Ð¾ÐµÐºÑ‚, Ð²ÐºÐ»ÑŽÑ‡Ð°Ñ Ð´ÐµÐ½ÑŒÐ³Ð¸, ÑÑ€Ð¾ÐºÐ¸ Ð¸ Ð¾Ñ‡ÐµÑ€ÐµÐ´Ð¸. Ð¡Ð¿Ð¸ÑÐ¾Ðº
    Ð¾Ñ‚Ð´ÐµÐ»ÑŒÐ½Ñ‹Ð¹ Ð¿Ð¾ Ñ‚Ð¾Ð¹ Ð¶Ðµ Ð¿Ñ€Ð¸Ñ‡Ð¸Ð½Ðµ, Ð¿Ð¾ ÐºÐ°ÐºÐ¾Ð¹ Ð¾Ð½Ð¸ Ð½Ðµ ÑÐ¼ÐµÑˆÐ¸Ð²Ð°ÑŽÑ‚ÑÑ Ð¿Ñ€Ð¸ Ð·Ð°Ð³Ñ€ÑƒÐ·ÐºÐµ.
    """
    _require_admin(session, key, "ÐŸÑ€ÐµÑÐµÑ‚Ñ‹ Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð¾Ð²")
    items: list[dict[str, Any]] = []
    for path in sorted(PRESET_DIR.glob("*.json")) if PRESET_DIR.is_dir() else []:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue  # Ð±Ð¸Ñ‚Ñ‹Ð¹ Ñ„Ð°Ð¹Ð» Ð½Ðµ Ð´Ð¾Ð»Ð¶ÐµÐ½ Ð¿Ñ€ÑÑ‚Ð°Ñ‚ÑŒ Ð¾ÑÑ‚Ð°Ð»ÑŒÐ½Ñ‹Ðµ
        project = data.get("project") if isinstance(data.get("project"), dict) else {}
        items.append({
            "id": path.stem,
            "name": str(project.get("name") or path.stem),
            "region": str(project.get("region") or ""),
            "schema_version": str(data.get("schema_version") or ""),
        })
    return {"presets": items}


