@app.post("/api/project-presets/import")
def import_project_preset(req: ProjectPresetRequest) -> dict[str, Any]:
    """ÐŸÑ€ÐµÑÐµÑ‚ Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð°: ÑÐ½Ð°Ñ‡Ð°Ð»Ð° Ð¿Ð¾ÐºÐ°Ð·Ð°Ñ‚ÑŒ, Ð¿Ð¾Ñ‚Ð¾Ð¼ Ð¿Ñ€Ð¸Ð¼ÐµÐ½ÑÑ‚ÑŒ.

    Ð ÐµÐ¶Ð¸Ð¼ `preview` Ð½Ð¸Ñ‡ÐµÐ³Ð¾ Ð½Ðµ Ð¼ÐµÐ½ÑÐµÑ‚ â€” Ð¾Ð½ Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð½Ð° Ð²Ð¾Ð¿Ñ€Ð¾Ñ Â«Ñ‡Ñ‚Ð¾ Ð±ÑƒÐ´ÐµÑ‚Â».
    Ð ÐµÐ¶Ð¸Ð¼ `apply` Ð²Ð¾Ð·Ð²Ñ€Ð°Ñ‰Ð°ÐµÑ‚ Ð³Ð¾Ñ‚Ð¾Ð²Ñ‹Ðµ Ð²Ð²Ð¾Ð´Ð½Ñ‹Ðµ Ð¸ Ð¢Ð­ÐŸ, ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ðµ ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° ÑÑ‚Ð°Ð²Ð¸Ñ‚
    ÑÐµÐ±Ðµ; ÑÐ°Ð¼ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚ Ð¿Ð¾-Ð¿Ñ€ÐµÐ¶Ð½ÐµÐ¼Ñƒ Ð´ÐµÐ»Ð°ÐµÑ‚ Ð´Ð²Ð¸Ð¶Ð¾Ðº, Ð° Ð½Ðµ Ð¸Ð¼Ð¿Ð¾Ñ€Ñ‚.
    """
    try:
        preview = project_preset.build_preview(req.preset)
        filled = {key: value for key, value in (req.filled or {}).items()
                  if value not in (None, "")}
        if filled:
            preview["inputs"].update(filled)
            # `social_mode` â€” Ð¿ÐµÑ€ÐµÐºÐ»ÑŽÑ‡Ð°Ñ‚ÐµÐ»ÑŒ Â«Ð¸Ð»Ð¸/Ð¸Ð»Ð¸Â»: Ð´ÐµÐ½ÐµÐ¶Ð½Ð°Ñ ÐºÐ¾Ð¼Ð¿ÐµÐ½ÑÐ°Ñ†Ð¸Ñ
            # Ð¾Ñ‚Ð¼ÐµÐ½ÑÐµÑ‚ ÑÑ‚Ñ€Ð¾Ð¹ÐºÑƒ ÑÐ¾Ñ†Ð¾Ð±ÑŠÐµÐºÑ‚Ð¾Ð² Ñ†ÐµÐ»Ð¸ÐºÐ¾Ð¼. Ð£ Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð°, ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ð¹ Ð¸ ÑÑ‚Ñ€Ð¾Ð¸Ñ‚
            # ÑˆÐºÐ¾Ð»Ñƒ, Ð¸ Ð¿Ð»Ð°Ñ‚Ð¸Ñ‚ Ð·Ð° ÑÑ‚Ð°Ð´Ð¸Ð¾Ð½, ÑÑ‚Ð¾ Ð¾Ñ‚Ð½ÑÐ»Ð¾ Ð±Ñ‹ ÑÑ‚Ñ€Ð¾Ð¹ÐºÑƒ Ð¸Ð· Ñ€Ð°ÑÑ…Ð¾Ð´Ð¾Ð² â€”
            # EBITDA Ñ€Ð¾ÑÐ»Ð° Ð¾Ñ‚ Ð´Ð¾Ð±Ð°Ð²Ð»ÐµÐ½Ð½Ð¾Ð³Ð¾ Ñ€Ð°ÑÑ…Ð¾Ð´Ð°. ÐŸÐ¾ÐºÐ° Ð¼Ð¾Ð´ÐµÐ»ÑŒ Ð½Ðµ ÑƒÐ¼ÐµÐµÑ‚
            # ÑÑ‡Ð¸Ñ‚Ð°Ñ‚ÑŒ Ð¾Ð±Ðµ Ð½Ð°Ð³Ñ€ÑƒÐ·ÐºÐ¸ Ñ€Ð°Ð·Ð¾Ð¼, Ñ€ÐµÐ¶Ð¸Ð¼ Ð½Ðµ Ñ‚Ñ€Ð¾Ð³Ð°ÐµÐ¼, Ð° ÑÑƒÐ¼Ð¼Ñƒ Ð¿Ð¾ÐºÐ°Ð·Ñ‹Ð²Ð°ÐµÐ¼
            # Ð¾Ñ‚Ð´ÐµÐ»ÑŒÐ½Ð¾, Ñ‡Ñ‚Ð¾Ð±Ñ‹ Ð¾Ð½Ð° Ð½Ðµ Ð²Ñ‹Ð³Ð»ÑÐ´ÐµÐ»Ð° ÑƒÑ‡Ñ‚Ñ‘Ð½Ð½Ð¾Ð¹.
            builds_social = any(float(preview["inputs"].get(key) or 0) > 0
                                for key in ("school_places", "kindergarten_places",
                                            "clinic_capacity"))
            if "social_compensation_mln" in filled:
                preview["inputs"]["social_mode"] = (
                    SOCIAL_MODE_BOTH if builds_social else "Ð”ÐµÐ½ÐµÐ¶Ð½Ð°Ñ ÐºÐ¾Ð¼Ð¿ÐµÐ½ÑÐ°Ñ†Ð¸Ñ")
            preview["notes"].append({
                "value": "", "origin": "source", "input_key": "", "input_unit": "",
                "note": "Ð²Ð²ÐµÐ´ÐµÐ½Ð¾ Ð²Ñ€ÑƒÑ‡Ð½ÑƒÑŽ Ð½Ð° ÑÐºÑ€Ð°Ð½Ðµ Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐºÐ¸: "
                        + ", ".join(sorted(filled)),
            })
    except project_preset.PresetError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"ÐŸÑ€ÐµÑÐµÑ‚ Ð½Ðµ Ñ€Ð°Ð·Ð¾Ð±Ñ€Ð°Ð½: {exc}") from exc

    labels = {name: title for group in FIELD_GROUPS for name, title, *_ in group[1]}
    tep_labels = {key: str(value.get("label") or key) for key, value in TEP_DEFAULT.items()}
    tep_current = req.tep or {}
    tep_rows: list[dict[str, Any]] = []
    for key, values in preview["tep"].items():
        current = tep_current.get(key) or {}
        for field, new_value in values.items():
            old_value = float(current.get(field) or 0.0)
            if abs(float(new_value or 0.0) - old_value) < 1e-6:
                continue
            tep_rows.append({
                "key": f"{key}.{field}", "label": f"{tep_labels.get(key, key)} Â· {field}",
                "was": old_value, "becomes": new_value,
                "action": "Ð·Ð°Ð¼ÐµÐ½Ð¸Ñ‚ÑÑ" if old_value else "Ð·Ð°Ð¿Ð¾Ð»Ð½Ð¸Ñ‚ÑÑ",
            })

    preview["diff"] = {
        "inputs": _preset_diff(req.inputs or {}, preview["inputs"], labels),
        "tep": tep_rows,
    }
    if req.mode == "apply":
        # ÐŸÑ€ÐµÑÐµÑ‚ Ð´Ð¾Ð¿Ð¾Ð»Ð½ÑÐµÑ‚ Ð¿Ñ€Ð¾ÐµÐºÑ‚, Ð° Ð½Ðµ Ð·Ð°Ð¼ÐµÐ½ÑÐµÑ‚ ÐµÐ³Ð¾: Ð¿Ð¾Ð»Ñ, ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ñ… Ð¾Ð½ Ð½Ðµ
        # ÐºÐ°ÑÐ°ÐµÑ‚ÑÑ, Ð¾ÑÑ‚Ð°ÑŽÑ‚ÑÑ ÐºÐ°Ðº Ð±Ñ‹Ð»Ð¸ â€” Ð¿Ñ€Ð°Ð²Ð¸Ð»Ð¾ Â«Ð¸Ð¼Ð¿Ð¾Ñ€Ñ‚ Ð½Ðµ Ð»Ð¾Ð¼Ð°ÐµÑ‚ Ñ€ÑƒÑ‡Ð½Ð¾Ð¹ Ð²Ð²Ð¾Ð´Â».
        preview["applied_inputs"] = {**(req.inputs or {}), **preview["inputs"]}
        applied_tep = {key: dict(value) for key, value in (req.tep or {}).items()}
        for key, values in preview["tep"].items():
            applied_tep.setdefault(key, {})
            applied_tep[key].update(values)
        preview["applied_tep"] = applied_tep
    return preview


_ASSETS_DIR = Path(__file__).resolve().parent / "assets"
_ASSET_CACHE_HEADERS = {"Cache-Control": "public, max-age=604800"}


@app.get("/assets/{name}", include_in_schema=False)
def developaid_asset(name: str) -> Response:
    """ÐšÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¸ Ð¿Ñ€Ð¸Ð»Ð¾Ð¶ÐµÐ½Ð¸Ñ. Ð›ÐµÐ¶Ð°Ñ‚ Ñ„Ð°Ð¹Ð»Ð°Ð¼Ð¸ Ð¸ Ð¾Ñ‚Ð´Ð°ÑŽÑ‚ÑÑ Ð°Ð´Ñ€ÐµÑÐ¾Ð¼ Ñ ÐºÑÑˆÐµÐ¼.

    Ð’ÑˆÐ¸Ð²Ð°Ñ‚ÑŒ Ð¸Ñ… Ð² `PAGE` Ð½ÐµÐ»ÑŒÐ·Ñ: ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° Ð¾Ñ‚Ð´Ð°Ñ‘Ñ‚ÑÑ Ð½Ð° ÐºÐ°Ð¶Ð´Ñ‹Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ Ñ†ÐµÐ»Ð¸ÐºÐ¾Ð¼, Ð¸
    Ð²ÐµÑ ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¸ Ð¿Ð»Ð°Ñ‚Ð¸Ð»ÑÑ Ð±Ñ‹ ÐºÐ°Ð¶Ð´Ñ‹Ð¼ Ð¾Ñ‚ÐºÑ€Ñ‹Ñ‚Ð¸ÐµÐ¼ â€” Ð² Ñ‚Ð¾Ð¼ Ñ‡Ð¸ÑÐ»Ðµ Ñ Ñ‚ÐµÐ»ÐµÑ„Ð¾Ð½Ð°.
    """
    if not re.fullmatch(r"[a-z0-9._-]{1,64}", name) or "/" in name:
        raise HTTPException(status_code=404, detail="ÐÐµÑ‚ Ñ‚Ð°ÐºÐ¾Ð³Ð¾ Ñ„Ð°Ð¹Ð»Ð°.")
    path = _ASSETS_DIR / name
    if not path.is_file():
        raise HTTPException(status_code=404, detail="ÐÐµÑ‚ Ñ‚Ð°ÐºÐ¾Ð³Ð¾ Ñ„Ð°Ð¹Ð»Ð°.")
    types = {".webp": "image/webp", ".png": "image/png", ".svg": "image/svg+xml"}
    media = types.get(path.suffix.lower())
    if not media:
        raise HTTPException(status_code=404, detail="Ð¢Ð°ÐºÐ¾Ð¹ Ñ‚Ð¸Ð¿ Ñ„Ð°Ð¹Ð»Ð¾Ð² Ð½Ðµ Ð¾Ñ‚Ð´Ð°Ñ‘Ñ‚ÑÑ.")
    return Response(path.read_bytes(), media_type=media, headers=_ASSET_CACHE_HEADERS)


