def _nspd_search_features(query: str) -> list[dict[str, Any]]:
    cache_key = f"nspd:search:{query}"
    cached = _land_cache_get(cache_key)
    if cached is not None:
        return cached
    params = urllib.parse.urlencode({
        "query": query,
        "thematicSearchId": _NSPD_LAND_THEMATIC_ID,
        "CRS": "EPSG:4326",
    })
    payload = _land_fetch_json(
        f"{_NSPD_BASE_URL}/api/geoportal/v2/search/geoportal?{params}",
        service="Ð¡ÐµÑ€Ð²Ð¸Ñ ÐÐ¡ÐŸÐ”",
    )
    features = _nspd_features(payload)
    # ÐŸÑƒÑÑ‚Ð¾Ð¹ Ð¾Ñ‚Ð²ÐµÑ‚ Ð½Ðµ ÐºÑÑˆÐ¸Ñ€ÑƒÐµÑ‚ÑÑ: ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð½Ðµ Ð½Ð° ÐºÐ°Ð¶Ð´Ñ‹Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ, Ð¸
    # Ð¿Ñ€Ð¸Ð»Ð¸Ð¿ÑˆÐ¸Ð¹ Ð² ÐºÑÑˆÐµ Ð¿Ñ€Ð¾Ð¼Ð°Ñ… 15 Ð¼Ð¸Ð½ÑƒÑ‚ Ð²Ñ‹Ð´Ð°Ð²Ð°Ð» Â«ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº Ð½Ðµ Ð½Ð°Ð¹Ð´ÐµÐ½Â» Ð½Ð° Ð²ÑÐµ
    # Ð¿Ð¾Ð²Ñ‚Ð¾Ñ€Ñ‹ â€” Ñ‚Ð°Ðº Ð¸Ð· 22 ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð² ÐœÑ‹Ñ‚Ð¸Ñ‰ ÑÑ‡Ð¸Ñ‚Ð°Ð»Ð¸ÑÑŒ 20, Ð° Ð¿Ð»Ð¾Ñ‰Ð°Ð´ÑŒ Ñ‚ÐµÑ€Ñ€Ð¸Ñ‚Ð¾Ñ€Ð¸Ð¸
    # Ð¼Ð¾Ð»Ñ‡Ð° Ñ‚ÐµÑ€ÑÐ»Ð° Ð²Ð¾ÑÐµÐ¼ÑŒ Ð³ÐµÐºÑ‚Ð°Ñ€Ð¾Ð².
    if features:
        _land_cache_put(cache_key, features)
    return features


def _nspd_point_features(lat: float, lng: float) -> list[dict[str, Any]]:
    """Ð£Ñ‡Ð°ÑÑ‚ÐºÐ¸ Ð² Ñ‚Ð¾Ñ‡ÐºÐµ: ÑÐ½Ð°Ñ‡Ð°Ð»Ð° Ð¿Ð¾Ð¸ÑÐº Ð¿Ð¾ ÐºÐ¾Ð¾Ñ€Ð´Ð¸Ð½Ð°Ñ‚Ð°Ð¼, Ð·Ð°Ñ‚ÐµÐ¼ WMS-Ð·Ð°Ð¿Ñ€Ð¾Ñ ÑÐ»Ð¾Ñ Ð—Ð£.

    Ð¢ÐµÐºÑÑ‚Ð¾Ð²Ñ‹Ð¹ Ð¿Ð¾Ð¸ÑÐº Â«lat lngÂ» Ð¸ Ð¿Ñ€ÐµÐ¶Ð½Ð¸Ð¹ GET /api/geoportal/v1/intersects Ð½Ð°
    Ñ‚Ð¾Ñ‡ÐºÐ°Ñ… Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÑŽÑ‚ Ð¿ÑƒÑÑ‚Ð¾Ñ‚Ð¾Ð¹ Ð´Ð°Ð¶Ðµ Ñ‚Ð°Ð¼, Ð³Ð´Ðµ ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº Ñ‚Ð¾Ñ‡Ð½Ð¾ ÐµÑÑ‚ÑŒ. Ð Ð°Ð±Ð¾Ñ‡Ð¸Ð¹ Ð¿ÑƒÑ‚ÑŒ â€”
    Ñ‚Ð¾Ñ‚, ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ð¼ ÑÐ°Ð¼Ð° ÐºÐ°Ñ€Ñ‚Ð° ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð½Ð° ÐºÐ»Ð¸Ðº: WMS GetFeatureInfo ÑÐ»Ð¾Ñ
    Â«Ð—ÐµÐ¼ÐµÐ»ÑŒÐ½Ñ‹Ðµ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¸ Ð¸Ð· Ð•Ð“Ð ÐÂ» Ð¿Ð¾ Ð¿Ð¸ÐºÑÐµÐ»ÑŽ Ñ‚Ð°Ð¹Ð»Ð° (ÑÐ²ÐµÑ€ÐµÐ½Ð¾ Ñ pynspd 1.1.13).
    """
    try:
        features = _nspd_search_features(f"{lat} {lng}")
    except HTTPException:
        features = []
    if features:
        return features
    # Ð¢Ð°Ð¹Ð» web-Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð°, Ð² ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ð¹ Ð¿Ð¾Ð¿Ð°Ð´Ð°ÐµÑ‚ Ñ‚Ð¾Ñ‡ÐºÐ°; zoom 24 â€” Ð¼Ð°ÐºÑÐ¸Ð¼ÑƒÐ¼ Ñ‚Ð¾Ñ‡Ð½Ð¾ÑÑ‚Ð¸.
    zoom = 24
    tiles = 1 << zoom
    tile_size = 512
    lat_rad = math.radians(lat)
    xtile = int((lng + 180.0) / 360.0 * tiles)
    ytile = int((1.0 - math.asinh(math.tan(lat_rad)) / math.pi) / 2.0 * tiles)
    west = xtile / tiles * 360.0 - 180.0
    east = (xtile + 1) / tiles * 360.0 - 180.0
    north = math.degrees(math.atan(math.sinh(math.pi * (1.0 - 2.0 * ytile / tiles))))
    south = math.degrees(math.atan(math.sinh(math.pi * (1.0 - 2.0 * (ytile + 1) / tiles))))
    i = int((lng - west) / (east - west) * tile_size)
    j = int((lat - south) / (north - south) * tile_size)
    params = urllib.parse.urlencode({
        "REQUEST": "GetFeatureInfo",
        "SERVICE": "WMS",
        "VERSION": "1.3.0",
        "INFO_FORMAT": "application/json",
        "FORMAT": "image/png",
        "STYLES": "",
        "TRANSPARENT": "true",
        "QUERY_LAYERS": _NSPD_LANDS_LAYER_ID,
        "LAYERS": _NSPD_LANDS_LAYER_ID,
        "WIDTH": tile_size,
        "HEIGHT": tile_size,
        "I": i,
        # ÐŸÐ¸ÐºÑÐµÐ»Ð¸ WMS Ð¾Ñ‚ÑÑ‡Ð¸Ñ‚Ñ‹Ð²Ð°ÑŽÑ‚ÑÑ Ð¾Ñ‚ Ð²ÐµÑ€Ñ…Ð½ÐµÐ³Ð¾ ÐºÑ€Ð°Ñ, Ð¸Ð½Ñ‚ÐµÑ€Ð¿Ð¾Ð»ÑÑ†Ð¸Ñ â€” Ð¾Ñ‚ ÑŽÐ¶Ð½Ð¾Ð³Ð¾.
        "J": tile_size - j,
        "CRS": "EPSG:4326",
        "BBOX": f"{west},{south},{east},{north}",
        # Ð‘ÐµÐ· FEATURE_COUNT ÑÐµÑ€Ð²Ð¸Ñ Ð¾Ñ‚Ð´Ð°Ñ‘Ñ‚ Ð¾Ð´Ð¸Ð½ Ð¾Ð±ÑŠÐµÐºÑ‚ Ð´Ð°Ð¶Ðµ Ð½Ð° Ð³Ñ€Ð°Ð½Ð¸Ñ†Ðµ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð².
        "FEATURE_COUNT": "10",
    })
    try:
        payload = _land_fetch_json(
            f"{_NSPD_BASE_URL}/api/aeggis/v3/{_NSPD_LANDS_LAYER_ID}/wms?{params}",
            service="Ð¡ÐµÑ€Ð²Ð¸Ñ ÐÐ¡ÐŸÐ”",
        )
    except HTTPException:
        return []
    return _nspd_features(payload)


# ÐŸÐ¾Ð´Ð»Ð¾Ð¶ÐºÐ° ÐºÐ°Ñ€Ñ‚Ñ‹ Ð¿Ð¾Ð´ ÐºÐ¾Ð½Ñ‚ÑƒÑ€Ð¾Ð¼ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°: WMS GetMap Ñ‚Ð¾Ð³Ð¾ Ð¶Ðµ ÑÐ»Ð¾Ñ Ð—Ð£, ÐºÐ¾Ñ‚Ð¾Ñ€Ñ‹Ð¼
# Ñ€Ð°Ð±Ð¾Ñ‚Ð°ÐµÑ‚ Ñ‚Ð¾Ñ‡ÐµÑ‡Ð½Ñ‹Ð¹ Ð¿Ð¾Ð¸ÑÐº. ÐšÑÑˆ Ð¼Ð°Ð»ÐµÐ½ÑŒÐºÐ¸Ð¹ Ð¸ Ñ TTL â€” ÐºÐ°Ñ€Ñ‚Ð° Ð½Ðµ Ð¼ÐµÐ½ÑÐµÑ‚ÑÑ Ð¾Ñ‚
# Ð·Ð°Ð¿Ñ€Ð¾ÑÐ° Ðº Ð·Ð°Ð¿Ñ€Ð¾ÑÑƒ, Ð° ÐÐ¡ÐŸÐ” Ð½Ðµ Ð»ÑŽÐ±Ð¸Ñ‚ Ñ‡Ð°ÑÑ‚Ñ‹Ñ… Ð¾Ð±Ñ€Ð°Ñ‰ÐµÐ½Ð¸Ð¹.
