# Ð²Ð¾Ð´Ð° Ð¸ Ð¿Ð¾Ð´Ð¿Ð¸ÑÐ¸ Ñ€Ð°Ð¹Ð¾Ð½Ð¾Ð² ÐµÑÑ‚ÑŒ Ñ‚Ð¾Ð»ÑŒÐºÐ¾ Ñƒ Ð½Ð°ÑÑ‚Ð¾ÑÑ‰ÐµÐ¹ ÐºÐ°Ñ€Ñ‚Ñ‹, Ð¿Ð¾ÑÑ‚Ð¾Ð¼Ñƒ Ð¿Ð¾Ð´Ð»Ð¾Ð¶ÐºÐ°
# Ð±ÐµÑ€Ñ‘Ñ‚ÑÑ Ñ‚Ð°Ð¹Ð»Ð°Ð¼Ð¸ OSM Ð¸ ÑÐºÐ»ÐµÐ¸Ð²Ð°ÐµÑ‚ÑÑ **Ð½Ð° ÑÐµÑ€Ð²ÐµÑ€Ðµ**: Ð±Ñ€Ð°ÑƒÐ·ÐµÑ€ Ð¿Ð¾Ð»ÑƒÑ‡Ð°ÐµÑ‚ Ð¾Ð´Ð½Ñƒ
# ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÑƒ, Ñ…Ð¾Ð´Ð¸Ñ‚ÑŒ Ð½Ð°Ñ€ÑƒÐ¶Ñƒ ÐµÐ¼Ñƒ Ð½Ðµ Ð¿Ñ€Ð¸Ñ…Ð¾Ð´Ð¸Ñ‚ÑÑ, Ð¸ Ð² Ð¿ÐµÑ‡Ð°Ñ‚ÑŒ ÑÑ‚Ð° ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ° ÑƒÑ…Ð¾Ð´Ð¸Ñ‚
# Ñ†ÐµÐ»Ð¸ÐºÐ¾Ð¼. ÐÐ´Ñ€ÐµÑ Ð²Ñ‹Ð½ÐµÑÐµÐ½ Ð² Ð¿ÐµÑ€ÐµÐ¼ÐµÐ½Ð½ÑƒÑŽ: ÑÐ²Ð¾Ð¹ Ñ‚Ð°Ð¹Ð»Ð¾Ð²Ñ‹Ð¹ ÑÐµÑ€Ð²ÐµÑ€ Ð¿Ð¾Ð´ÑÑ‚Ð°Ð²Ð»ÑÐµÑ‚ÑÑ
# Ð¾Ð´Ð½Ð¾Ð¹ ÑÑ‚Ñ€Ð¾ÐºÐ¾Ð¹, Ð±ÐµÐ· Ð¿Ñ€Ð°Ð²ÐºÐ¸ ÐºÐ¾Ð´Ð°.
