@app.get("/land/screening", include_in_schema=False)
def land_screening(cad: str = "", min_area_sqm: float | None = None) -> dict[str, Any]:
    """ÐžÑ†ÐµÐ½ÐºÐ° ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð´Ð¾ Ñ„Ð¸Ð½Ð¼Ð¾Ð´ÐµÐ»Ð¸: Ñ‡Ñ‚Ð¾ Ð¼ÐµÑˆÐ°ÐµÑ‚ ÑÑ‚Ñ€Ð¾Ð¸Ñ‚ÑŒ, Ð¿Ð¾ ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ð¾Ð¼Ñƒ Ð½Ð¾Ð¼ÐµÑ€Ñƒ.

    Ð¡Ð°Ð¼Ð¾ÑÑ‚Ð¾ÑÑ‚ÐµÐ»ÑŒÐ½Ð°Ñ Ñ†ÐµÐ½Ð½Ð¾ÑÑ‚ÑŒ Ð¿Ñ€Ð¾Ð´ÑƒÐºÑ‚Ð°: Ñ‡ÐµÐ»Ð¾Ð²ÐµÐº Ð²Ð²Ð¾Ð´Ð¸Ñ‚ Ð½Ð¾Ð¼ÐµÑ€ Ð¸ ÑÑ€Ð°Ð·Ñƒ Ð²Ð¸Ð´Ð¸Ñ‚
    Ð¾Ð³Ñ€Ð°Ð½Ð¸Ñ‡ÐµÐ½Ð¸Ñ â€” Ð—ÐžÐ£Ð˜Ð¢, ÐžÐžÐŸÐ¢, ÐºÑ€Ð°ÑÐ½Ñ‹Ðµ Ð»Ð¸Ð½Ð¸Ð¸, Ñ‚Ð¸Ð¿ Ñ‚ÐµÑ€Ñ€Ð¸Ñ‚Ð¾Ñ€Ð¸Ð°Ð»ÑŒÐ½Ð¾Ð¹ Ð·Ð¾Ð½Ñ‹ â€” Ñ
    Ñ€ÐµÐµÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¼ Ð½Ð¾Ð¼ÐµÑ€Ð¾Ð¼ Ð¸ Ð´Ð¾ÐºÑƒÐ¼ÐµÐ½Ñ‚Ð¾Ð¼-Ð¾ÑÐ½Ð¾Ð²Ð°Ð½Ð¸ÐµÐ¼, Ð±ÐµÐ· Ð²ÑÑÐºÐ¾Ð³Ð¾ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚Ð° ÑÐºÐ¾Ð½Ð¾Ð¼Ð¸ÐºÐ¸.
    ÐžÐ´Ð¸Ð½ ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº â€” ÐºÐ¾Ñ€Ð¾Ñ‚ÐºÐ¾, Ð½ÐµÑÐºÐ¾Ð»ÑŒÐºÐ¾ â€” ÑÐ²Ð¾Ð´ Ð¿Ð»ÑŽÑ Ñ€Ð°Ð·Ð±Ð¸Ð²ÐºÐ° (Ñ€ÐµÑˆÐµÐ½Ð¸Ðµ Ð²Ð»Ð°Ð´ÐµÐ»ÑŒÑ†Ð°).
    Ð§Ð¸ÑÐ»Ð° Ð¸ Ñ„Ð°ÐºÑ‚Ñ‹ Ð´Ð°Ñ‘Ñ‚ ÐÐ¡ÐŸÐ”, Ð²Ñ‹Ð²Ð¾Ð´ Ð½Ðµ Ñ€Ð°Ð·Ñ€ÐµÑˆÐ¸Ñ‚ÐµÐ»ÑŒÐ½Ñ‹Ð¹.
    """
    remote = _core_api_url("/land/screening")
    if remote:
        try:
            query = {"cad": cad}
            if min_area_sqm is not None:
                query["min_area_sqm"] = min_area_sqm
            with urllib.request.urlopen(
                    urllib.request.Request(
                        remote + "?" + urllib.parse.urlencode(query),
                        headers={"Accept": "application/json"}),
                    timeout=180) as response:
                return json.loads(response.read().decode("utf-8"))
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"Ð¯Ð´Ñ€Ð¾ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð¾: {exc}")

    numbers = [n for n in re.split(r"[\s,;]+", _land_text(cad)) if n.strip()]
    numbers = [n for n in numbers if re.match(r"^\d{2}:\d{2}:\d{6,8}:\d+$", n)]
    if not numbers:
        raise HTTPException(status_code=400, detail="cad: ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¹ Ð½Ð¾Ð¼ÐµÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°.")
    # ÐŸÑ€ÐµÐ´ÐµÐ» Ñ‚Ð¾Ñ‚ Ð¶Ðµ, Ñ‡Ñ‚Ð¾ Ñƒ Ð¿Ð¾Ð¸ÑÐºÐ° ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð²: Ñ‚Ñ€Ð¸Ð´Ñ†Ð°Ñ‚ÑŒ. Ð”ÐµÑÑÑ‚Ð¸ Ð½Ðµ Ñ…Ð²Ð°Ñ‚Ð°Ð»Ð¾ â€”
    # Ð¿Ð»Ð¾Ñ‰Ð°Ð´ÐºÐ° Ð¸Ð· Ð´Ð²Ð°Ð´Ñ†Ð°Ñ‚Ð¸ Ð´Ð²ÑƒÑ… ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð² Ð¿Ñ€Ð¾Ð²ÐµÑ€ÑÐ»Ð°ÑÑŒ Ð½Ð°Ð¿Ð¾Ð»Ð¾Ð²Ð¸Ð½Ñƒ (Ð·Ð°Ð¼ÐµÑ‡Ð°Ð½Ð¸Ðµ
    # Ð²Ð»Ð°Ð´ÐµÐ»ÑŒÑ†Ð°, 19.08.2026). Ð£ÑÐµÑ‡ÐµÐ½Ð¸Ðµ Ð²ÑÑ‘ Ñ€Ð°Ð²Ð½Ð¾ Ð½Ð°Ð·Ñ‹Ð²Ð°ÐµÑ‚ÑÑ Ð²ÑÐ»ÑƒÑ…: Ð¼Ð¾Ð»Ñ‡Ð°Ð»Ð¸Ð²Ð¾Ðµ
    # Ñ‡Ð¸Ñ‚Ð°ÐµÑ‚ÑÑ ÐºÐ°Ðº Â«Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐµÐ½Ð¾ Ð²ÑÑ‘Â».
    requested = len(numbers)
    numbers = numbers[:30]
    threshold = (_LAND_SCREENING_MIN_AREA_SQM if min_area_sqm is None
                 else max(0.0, float(min_area_sqm)))

    parcels: list[dict[str, Any]] = []
    for number in numbers:
        cached = _LAND_SCREENING_CACHE.get(number)
        if cached and time.time() - cached[0] < _LAND_SCREENING_TTL_SECONDS:
            parcels.append(cached[1])
            continue
        try:
            features = _nspd_search_features(number)
            probe_error = ""
        except Exception as exc:
            features = []
            probe_error = _land_text(getattr(exc, "detail", "") or str(exc)) or "Ð·Ð°Ð¿Ñ€Ð¾Ñ Ð½Ðµ Ð¿Ñ€Ð¾ÑˆÑ‘Ð»"
        # ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð½Ðµ Ð½Ð° ÐºÐ°Ð¶Ð´Ñ‹Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ: Ð½Ð° Ð¿Ð»Ð¾Ñ‰Ð°Ð´ÐºÐµ Ð¸Ð· Ð´Ð²Ð°Ð´Ñ†Ð°Ñ‚Ð¸ Ð´Ð²ÑƒÑ…
        # Ð½Ð¾Ð¼ÐµÑ€Ð¾Ð² ÑÐ²ÐµÐ´ÐµÐ½Ð¸Ñ Ð¿Ñ€Ð¸ÑˆÐ»Ð¸ Ð¿Ð¾ Ð´ÐµÑÑÑ‚Ð¸, Ð¸ Ð´Ð²ÐµÐ½Ð°Ð´Ñ†Ð°Ñ‚ÑŒ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð² Ð²Ñ‹Ð³Ð»ÑÐ´ÐµÐ»Ð¸
        # Ð½ÐµÑÑƒÑ‰ÐµÑÑ‚Ð²ÑƒÑŽÑ‰Ð¸Ð¼Ð¸ (Ð·Ð°Ð¼ÐµÑ‡Ð°Ð½Ð¸Ðµ Ð²Ð»Ð°Ð´ÐµÐ»ÑŒÑ†Ð°, 19.08.2026). ÐžÐ´Ð¸Ð½ Ð¿Ð¾Ð²Ñ‚Ð¾Ñ€
        # Ð²Ð¾Ð·Ð²Ñ€Ð°Ñ‰Ð°ÐµÑ‚ Ð±Ð¾Ð»ÑŒÑˆÑƒÑŽ Ñ‡Ð°ÑÑ‚ÑŒ â€” Ð¼Ð¾Ð»Ñ‡Ð°Ð»Ð¸Ð²Ð°Ñ Ð¿Ð¾Ñ‚ÐµÑ€Ñ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð´Ð¾Ñ€Ð¾Ð¶Ðµ Ð·Ð°Ð¿Ñ€Ð¾ÑÐ°.
        if not features:
            time.sleep(_LAND_RETRY_PAUSE_SECONDS)
            try:
                features = _nspd_search_features(number)
                if features:
                    probe_error = ""
            except Exception as exc:
                probe_error = probe_error or _land_text(getattr(exc, "detail", "") or str(exc))
        matched = None
        for feature in features:
            options = _nspd_options(feature)
            if _land_text(_nspd_value(options, "cadastral_number")) == number:
                matched = feature
                break
        matched = matched or (features[0] if features else None)
        if matched is None:
            # Ð¡Ð¾Ñ€Ð²Ð°Ð½Ð½Ñ‹Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ Ð¸ Ð¿ÑƒÑÑ‚Ð¾Ð¹ Ð¾Ñ‚Ð²ÐµÑ‚ â€” Ñ€Ð°Ð·Ð½Ñ‹Ðµ Ð²ÐµÑ‰Ð¸: Ð¿ÐµÑ€Ð²Ð¾Ðµ Ð³Ð¾Ð²Ð¾Ñ€Ð¸Ñ‚ Ð¾
            # Ð½Ð°Ñ, Ð²Ñ‚Ð¾Ñ€Ð¾Ðµ Ð¾Ð± ÑƒÑ‡Ð°ÑÑ‚ÐºÐµ. Ð¡ÐºÐ»Ð°Ð´Ñ‹Ð²Ð°Ñ‚ÑŒ Ð¸Ñ… Ð² Ð¾Ð´Ð½Ñƒ ÑÑ‚Ñ€Ð¾ÐºÑƒ Ð·Ð½Ð°Ñ‡Ð¸Ñ‚
            # Ð²Ñ‹Ð´Ð°Ð²Ð°Ñ‚ÑŒ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð¾ÑÑ‚ÑŒ ÐÐ¡ÐŸÐ” Ð·Ð° Ð¾Ñ‚ÑÑƒÑ‚ÑÑ‚Ð²Ð¸Ðµ ÑÐ²ÐµÐ´ÐµÐ½Ð¸Ð¹.
            parcels.append({"cadastral_number": number, "found": False,
                            "probe_failed": bool(probe_error),
                            "note": (f"Ð—Ð°Ð¿Ñ€Ð¾Ñ Ð² ÐÐ¡ÐŸÐ” Ð½Ðµ Ð¿Ñ€Ð¾ÑˆÑ‘Ð»: {probe_error}" if probe_error
                                     else "Ð¡Ð²ÐµÐ´ÐµÐ½Ð¸Ñ Ð•Ð“Ð Ð Ð¿Ð¾ Ð½Ð¾Ð¼ÐµÑ€Ñƒ Ð½Ðµ Ð¿Ð¾Ð»ÑƒÑ‡ÐµÐ½Ñ‹.")})
            continue
        options = _nspd_options(matched)
        center = _geometry_center(matched.get("geometry")) or {}
        findings: list[dict[str, Any]] = []
        # ÐœÐµÐ»ÐºÐ¸Ð¹ ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº Ð² Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐºÑƒ Ð½Ðµ Ð¸Ð´Ñ‘Ñ‚: ÑÐ²ÐµÐ´ÐµÐ½Ð¸Ñ Ð•Ð“Ð Ð Ð¿Ð¾ Ð½ÐµÐ¼Ñƒ ÑÑ‚Ð¾ÑÑ‚ Ð¾Ð´Ð¸Ð½
        # Ð·Ð°Ð¿Ñ€Ð¾Ñ, Ð° ÑÐºÑ€Ð¸Ð½Ð¸Ð½Ð³ â€” ÑˆÐµÑÑ‚ÑŒÐ´ÐµÑÑÑ‚ Ð´Ð²Ð°, Ð¸ Ð¿Ð¾ÑÐ°Ð´ÐºÑƒ Ð¾Ð½ Ð²ÑÑ‘ Ñ€Ð°Ð²Ð½Ð¾ Ð½Ðµ
        # Ð¾Ð¿Ñ€ÐµÐ´ÐµÐ»ÑÐµÑ‚. ÐŸÑ€Ð¾Ð¿ÑƒÑÐº Ð½Ðµ Ð²Ñ‹Ð´Ð°Ñ‘Ñ‚ÑÑ Ð·Ð° Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐºÑƒ: Ñƒ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° ÑÑ‚Ð¾Ð¸Ñ‚ Ð¿Ñ€Ð¸Ð·Ð½Ð°Ðº.
        parcel_area = _land_float(_nspd_value(options, "area_sqm")) or 0.0
        too_small = bool(threshold and parcel_area and parcel_area < threshold)
        if center and not too_small:
            # ÐšÐ¾Ð½Ñ‚ÑƒÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð¸Ð´Ñ‘Ñ‚ Ð² ÑÐºÑ€Ð¸Ð½Ð¸Ð½Ð³: Ð·Ð¾Ð½Ñ‹ Ð½Ð°ÐºÐ»Ð°Ð´Ñ‹Ð²Ð°ÑŽÑ‚ÑÑ Ð½Ð° Ð½ÐµÐ³Ð¾, Ð¸
            # Ð²Ð¸Ð´Ð½Ð¾, ÑÑŠÐµÐ»Ð¸ Ð¾Ð½Ð¸ ÑƒÐ³Ð¾Ð» Ð¸Ð»Ð¸ Ð²ÐµÑÑŒ ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº.
            findings = _land_screen_findings(center["lat"], center["lng"],
                                             matched.get("geometry"))
            findings.sort(key=lambda f: _LAND_SCREEN_ORDER.get(f.get("flag_class"), 3))
        area = _land_float(_nspd_value(options, "area_sqm"))
        contour = _geometry_contours_merc(matched.get("geometry"))
        parcel = {
            "cadastral_number": number,
            "found": True,
            # Ð Ð¸ÑÑƒÐ½Ð¾Ðº Ð¿ÑÑ‚Ð½Ð°: ÐºÐ¾Ð½Ñ‚ÑƒÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð¸ Ð¾Ñ‡ÐµÑ€Ñ‚Ð°Ð½Ð¸Ñ Ð·Ð¾Ð½ Ð² Ð¾Ð´Ð½Ð¾Ð¹ Ð¿Ð»Ð¾ÑÐºÐ¾ÑÑ‚Ð¸.
            "contour_merc": contour,
            "address": _land_text(_nspd_value(options, "address")),
            "area_sqm": area,
            "area_ha": round(area / 10000.0, 4) if area else None,
            "category": _land_text(_nspd_value(options, "category")),
            "permitted_use": _land_text(_nspd_value(options, "permitted_use")),
            "center": center or None,
            "findings": findings,
            "too_small": too_small,
            "verdict": _land_screening_verdict(findings,
                                               probed=bool(center) and not too_small),
        }
        _LAND_SCREENING_CACHE[number] = (time.time(), parcel)
        parcels.append(parcel)

    everything = [f for p in parcels for f in p.get("findings", [])]
    probed = any(p.get("found") and p.get("center") for p in parcels)
    return {
        "parcels": parcels,
        "requested_count": requested,
        "checked_count": len(numbers),
        "min_area_sqm": threshold,
        "small_count": sum(1 for p in parcels if p.get("too_small")),
        "single": len(parcels) == 1,
        "verdict": _land_screening_verdict(everything, probed=probed),
        "calculated_at": datetime.now().strftime("%d.%m.%Y %H:%M"),
    }


def _land_zouit_findings(lat: float, lng: float) -> list[dict[str, Any]]:
    """ÐŸÐµÑ€ÐµÑÐµÐºÐ°ÑŽÑ‰Ð¸Ðµ Ñ‚Ð¾Ñ‡ÐºÑƒ Ð—ÐžÐ£Ð˜Ð¢ Ð¸Ð· ÐÐ¡ÐŸÐ” â€” ÑÑ‚Ñ€ÑƒÐºÑ‚ÑƒÑ€Ð¸Ñ€Ð¾Ð²Ð°Ð½Ð¾, Ð´Ð»Ñ ÑÐºÑ€Ð¸Ð½Ð¸Ð½Ð³Ð°.

    ÐŸÐ¾ ÐºÐ°Ð¶Ð´Ð¾Ð¼Ñƒ Ð¿Ð¾Ð´ÑÐ»Ð¾ÑŽ Ð—ÐžÐ£Ð˜Ð¢ ÑˆÐ»Ñ‘Ñ‚ GetFeatureInfo (v3) Ð¸ ÑÐ¾Ð±Ð¸Ñ€Ð°ÐµÑ‚ Ð½Ð°Ñ…Ð¾Ð´ÐºÐ¸:
    Ñ‚Ð¸Ð¿ Ð·Ð¾Ð½Ñ‹, Ð½Ð°Ð¸Ð¼ÐµÐ½Ð¾Ð²Ð°Ð½Ð¸Ðµ Ð¿Ð¾ Ð´Ð¾ÐºÑƒÐ¼ÐµÐ½Ñ‚Ñƒ, Ñ€ÐµÐµÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¹ Ð½Ð¾Ð¼ÐµÑ€ Ð³Ñ€Ð°Ð½Ð¸Ñ†Ñ‹, Ñ‚ÐµÐºÑÑ‚
    Ð¾Ð³Ñ€Ð°Ð½Ð¸Ñ‡ÐµÐ½Ð¸Ñ Ð¸ Ñ€ÐµÐºÐ²Ð¸Ð·Ð¸Ñ‚Ñ‹ ÑƒÑÑ‚Ð°Ð½Ð°Ð²Ð»Ð¸Ð²Ð°ÑŽÑ‰ÐµÐ³Ð¾ Ð´Ð¾ÐºÑƒÐ¼ÐµÐ½Ñ‚Ð°. Ð”ÑƒÐ±Ð»Ð¸ (Ð¾Ð´Ð¸Ð½ Ð¸ Ñ‚Ð¾Ñ‚ Ð¶Ðµ
    Ñ€ÐµÐµÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¹ Ð½Ð¾Ð¼ÐµÑ€ Ð¿Ñ€Ð¸Ñ…Ð¾Ð´Ð¸Ñ‚ Ð¸Ð· Ð½ÐµÑÐºÐ¾Ð»ÑŒÐºÐ¸Ñ… Ð¿Ð¾Ð´ÑÐ»Ð¾Ñ‘Ð²) Ð¾Ñ‚Ð±Ñ€Ð°ÑÑ‹Ð²Ð°ÑŽÑ‚ÑÑ. Ð¡Ð»Ð¾Ð¹,
    Ð¾Ñ‚Ð²ÐµÑ‚Ð¸Ð²ÑˆÐ¸Ð¹ Ð¾ÑˆÐ¸Ð±ÐºÐ¾Ð¹, Ð¿Ñ€Ð¾Ð¿ÑƒÑÐºÐ°ÐµÑ‚ÑÑ â€” Ð¾Ð´Ð½Ð° Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°Ñ Ð²ÐµÑ‚ÐºÐ° Ð½Ðµ Ñ€ÑƒÑˆÐ¸Ñ‚ ÑÐºÑ€Ð¸Ð½Ð¸Ð½Ð³.
    Ð’Ð¾Ð·Ð²Ñ€Ð°Ñ‰Ð°ÐµÑ‚ ÑÐ¿Ð¸ÑÐ¾Ðº; Ð¿ÑƒÑÑ‚Ð¾ â€” Ð¾Ð³Ñ€Ð°Ð½Ð¸Ñ‡ÐµÐ½Ð¸Ð¹ Ð² Ñ‚Ð¾Ñ‡ÐºÐµ Ð½Ðµ Ð¾Ð±Ð½Ð°Ñ€ÑƒÐ¶ÐµÐ½Ð¾ (Ð½Ðµ Â«Ð½ÐµÑ‚
    Ð—ÐžÐ£Ð˜Ð¢ Ð²Ð¾Ð¾Ð±Ñ‰ÐµÂ»: ÐÐ¡ÐŸÐ” Ð²Ð¸Ð´Ð¸Ñ‚ Ñ‚Ð¾Ð»ÑŒÐºÐ¾ Ð²Ð½ÐµÑÑ‘Ð½Ð½Ñ‹Ðµ Ð² Ð•Ð“Ð Ð).
    """
    findings: list[dict[str, Any]] = []
    seen: set[str] = set()
    for layer_id in _NSPD_ZOUIT_LAYERS:
        try:
            payload = _nspd_getfeatureinfo(lat, lng, layer_id, "v3")
        except Exception:
            continue
        for feature in _nspd_features(payload):
            options = _nspd_options(feature)
            reg_number = _land_text(options.get("reg_numb_border") or options.get("descr"))
            key = reg_number or _land_text(options.get("interactionId"))
            if not key or key in seen:
                continue
            seen.add(key)
            findings.append({
                "type_zone": _land_text(options.get("type_zone")),
                "name": _land_text(options.get("name_by_doc")) or _land_text(options.get("type_zone")),
                "reg_number": reg_number,
                "restriction": _land_text(options.get("content_restrict_encumbrances")),
                "document": _land_text(options.get("legal_act_document_name")),
                "document_number": _land_text(options.get("legal_act_document_number")),
                "document_date": _land_text(options.get("legal_act_document_date")),
                "layer_id": layer_id,
            })
    return findings


def _nspd_wms_map_png(west: float, south: float, east: float, north: float,
                      width: int, height: int) -> bytes:
    """ÐšÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ° ÑÐ»Ð¾Ñ Â«Ð—ÐµÐ¼ÐµÐ»ÑŒÐ½Ñ‹Ðµ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¸ Ð¸Ð· Ð•Ð“Ð ÐÂ» Ð¿Ð¾Ð´ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¹ bbox.

    Ð¤Ð¾Ñ€Ð¼Ð°Ñ‚ ÑÐ²ÐµÑ€ÐµÐ½ Ð¿Ñ€Ð¾Ð±Ð¾Ð¹ /land/map-probe Ð½Ð° Ð¿Ñ€Ð¾Ð´Ðµ (16.08.2026): ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð´Ð°Ñ‘Ñ‚
    PNG Ñ‚Ð¾Ð»ÑŒÐºÐ¾ Ð½Ð° EPSG:3857 Ñ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¼ bbox, EPSG:4326 Ð² Ð¾Ð±Ð¾Ð¸Ñ… Ð¿Ð¾Ñ€ÑÐ´ÐºÐ°Ñ…
    Ð¾ÑÐµÐ¹ Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ 404. ÐŸÑ€Ð¾Ð·Ñ€Ð°Ñ‡Ð½Ð¾ÑÑ‚ÑŒ true â€” ÐºÐ°Ðº Ð² Ð¿Ñ€Ð¾Ð±Ðµ; Ñ„Ð¾Ð½ Ð²Ñ‹Ñ€Ð°Ð²Ð½Ð¸Ð²Ð°ÐµÑ‚
    land_map_image.
    """
    params = urllib.parse.urlencode({
        "REQUEST": "GetMap",
        "SERVICE": "WMS",
        "VERSION": "1.3.0",
        "FORMAT": "image/png",
        "STYLES": "",
        "TRANSPARENT": "true",
        "LAYERS": _NSPD_LANDS_LAYER_ID,
        "WIDTH": int(width),
        "HEIGHT": int(height),
        "CRS": "EPSG:3857",
        "BBOX": f"{west},{south},{east},{north}",
    })
    request_headers = {
        "Accept": "image/png,image/*;q=0.9,*/*;q=0.5",
        "Accept-Language": "ru-RU,ru;q=0.9",
        "User-Agent": _LAND_LOOKUP_USER_AGENT,
    }
    request_headers.update(_NSPD_BROWSER_HEADERS)
    external_request = urllib.request.Request(
        f"{_NSPD_BASE_URL}/api/aeggis/v3/{_NSPD_LANDS_LAYER_ID}/wms?{params}",
        headers=request_headers,
    )
    # Ð¢Ð¾Ñ‚ Ð¶Ðµ TLS-Ñ„Ð¾Ð»Ð±ÑÐº, Ñ‡Ñ‚Ð¾ Ñƒ Ð¿Ð¾Ð¸ÑÐºÐ° (_land_fetch_json): ÑÐµÑ€Ñ‚Ð¸Ñ„Ð¸ÐºÐ°Ñ‚ ÐÐ¡ÐŸÐ” â€”
    # Ñ€Ð¾ÑÑÐ¸Ð¹ÑÐºÐ¸Ð¹ Ð£Ð¦, Ð¸ Ð±ÐµÐ· Ð¿Ð¾Ð²Ñ‚Ð¾Ñ€Ð° Ð±ÐµÐ· Ð¿Ñ€Ð¾Ð²ÐµÑ€ÐºÐ¸ ÐºÐ°Ñ€Ñ‚Ð° Ð¿Ð°Ð´Ð°Ð»Ð° Ñ
    # CERTIFICATE_VERIFY_FAILED. Ð¤Ð»Ð°Ð³ â€” Ð½Ð° Ð¿Ñ€Ð¾Ñ†ÐµÑÑ, Ð° Ð²Ð¾Ñ€ÐºÐµÑ€Ð¾Ð² Ð´Ð²Ð°: Ñ‡Ð¸Ñ‚Ð°Ñ‚ÑŒ ÐµÐ³Ð¾
    # Ð¼Ð°Ð»Ð¾, Ð½Ð°Ð´Ð¾ ÑƒÐ¼ÐµÑ‚ÑŒ Ð²Ð·Ð²Ð¾Ð´Ð¸Ñ‚ÑŒ Ð¸ Ð·Ð´ÐµÑÑŒ, Ð¸Ð½Ð°Ñ‡Ðµ ÐºÐ°Ñ€Ñ‚Ð° Ð¶Ð¸Ð²Ñ‘Ñ‚ Ñ‚Ð¾Ð»ÑŒÐºÐ¾ Ð² Ñ‚Ð¾Ð¼
    # Ð²Ð¾Ñ€ÐºÐµÑ€Ðµ, Ð³Ð´Ðµ Ð´Ð¾ Ð½ÐµÑ‘ ÑƒÐ¶Ðµ Ð¸ÑÐºÐ°Ð»Ð¸ ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº (ÑÐºÑ€Ð¸Ð½ÑˆÐ¾Ñ‚ Ð²Ð»Ð°Ð´ÐµÐ»ÑŒÑ†Ð°, 16.08.2026).
    global _nspd_tls_insecure
    context = ssl._create_unverified_context() if _nspd_tls_insecure else None
    try:
        with urllib.request.urlopen(
                external_request, timeout=_NSPD_TIMEOUT_SECONDS, context=context) as response:
            raw = response.read(4 * 1024 * 1024)
    except urllib.error.URLError as exc:
        if not (
            _NSPD_TLS_FALLBACK
            and not _nspd_tls_insecure
            and isinstance(getattr(exc, "reason", None), ssl.SSLError)
        ):
            raise
        _nspd_tls_insecure = True
        with urllib.request.urlopen(
                external_request, timeout=_NSPD_TIMEOUT_SECONDS,
                context=ssl._create_unverified_context()) as response:
            raw = response.read(4 * 1024 * 1024)
    if not raw.startswith(b"\x89PNG"):
        raise ValueError("ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð²ÐµÑ‚Ð¸Ð»Ð° Ð½Ðµ ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¾Ð¹")
    return raw


@app.get("/land/map-image", include_in_schema=False)
def land_map_image(bbox: str = "") -> Response:
    """ÐŸÐ¾Ð´Ð»Ð¾Ð¶ÐºÐ° ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ð¾Ð¹ ÐºÐ°Ñ€Ñ‚Ñ‹ Ð¿Ð¾Ð´ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¹ bbox ÐºÐ¾Ð½Ñ‚ÑƒÑ€Ð°.

    Ð¡Ñ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° Ð¿ÐµÑ€ÐµÐ´Ð°Ñ‘Ñ‚ Ñ€Ð¾Ð²Ð½Ð¾ Ñ‚Ð¾Ñ‚ bbox (Ñ Ð¿Ð¾Ð»ÐµÐ¼), Ð² ÐºÐ¾Ñ‚Ð¾Ñ€Ð¾Ð¼ Ñ€Ð¸ÑÑƒÐµÑ‚ SVG-ÐºÐ¾Ð½Ñ‚ÑƒÑ€,
    Ð° ÐÐ¡ÐŸÐ” Ð¿Ñ€Ð¸Ð½Ð¸Ð¼Ð°ÐµÑ‚ ÐµÐ³Ð¾ Ñ‚ÐµÐ¼ Ð¶Ðµ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð¾Ð¼ (EPSG:3857, ÑÐ²ÐµÑ€ÐµÐ½Ð¾ Ð¿Ñ€Ð¾Ð±Ð¾Ð¹) â€”
    Ð¿Ð¾Ð´Ð»Ð¾Ð¶ÐºÐ° Ð¸ ÐºÐ¾Ð½Ñ‚ÑƒÑ€ ÑÐ¾Ð²Ð¿Ð°Ð´Ð°ÑŽÑ‚ Ð¿Ð¸ÐºÑÐµÐ»ÑŒ Ð² Ð¿Ð¸ÐºÑÐµÐ»ÑŒ Ð±ÐµÐ· Ð¿ÐµÑ€ÐµÑÑ‡Ñ‘Ñ‚Ð¾Ð². Ð›ÑŽÐ±Ð¾Ð¹
    ÑÐ±Ð¾Ð¹ â€” 502, Ð¸ ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° Ð¿Ñ€Ð¾ÑÑ‚Ð¾ Ð¾ÑÑ‚Ð°Ñ‘Ñ‚ÑÑ Ñ Ñ‡Ð¸ÑÑ‚Ñ‹Ð¼ ÐºÐ¾Ð½Ñ‚ÑƒÑ€Ð¾Ð¼: Ð¿Ð¾Ð´Ð»Ð¾Ð¶ÐºÐ° â€”
    ÑƒÐºÑ€Ð°ÑˆÐµÐ½Ð¸Ðµ, Ð° Ð½Ðµ Ð´Ð°Ð½Ð½Ñ‹Ðµ.
    """
    remote = _core_api_url("/land/map-image")
    if remote:
        # ÐšÐ°Ðº /land/lookup: Render Ð´Ð¾ ÐÐ¡ÐŸÐ” Ð½Ðµ Ñ…Ð¾Ð´Ð¸Ñ‚ â€” Ð¿ÐµÑ€ÐµÑÑ‹Ð»Ð°ÐµÑ‚ Ð½Ð° ÑÐ´Ñ€Ð¾.
        try:
            with urllib.request.urlopen(
                    urllib.request.Request(
                        remote + "?" + urllib.parse.urlencode({"bbox": bbox}),
                        headers={"Accept": "image/png"}),
                    timeout=_NSPD_TIMEOUT_SECONDS) as response:
                raw = response.read(4 * 1024 * 1024)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"ÐŸÐ¾Ð´Ð»Ð¾Ð¶ÐºÐ° ÐºÐ°Ñ€Ñ‚Ñ‹ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°: {exc}")
        return Response(raw, media_type="image/png",
                        headers={"Cache-Control": "public, max-age=3600"})
    try:
        parts = [float(x) for x in str(bbox or "").split(",")]
    except ValueError:
        parts = []
    if len(parts) != 4:
        raise HTTPException(status_code=400, detail="bbox: minX,minY,maxX,maxY Ð² Ð¼ÐµÑ‚Ñ€Ð°Ñ… Ð²ÐµÐ±-Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð°.")
    min_x, min_y, max_x, max_y = parts
    span_x, span_y = max_x - min_x, max_y - min_y
    if not (0 < span_x <= 20000 and 0 < span_y <= 20000):
        # Ð‘Ð¾Ð»ÑŒÑˆÐµ 20 ÐºÐ¼ â€” ÑÑ‚Ð¾ ÑƒÐ¶Ðµ Ð½Ðµ ÐºÐ°Ñ€Ñ‚Ð¾Ñ‡ÐºÐ° ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°, Ð° ÐºÐ°Ñ€Ñ‚Ð° ÑÑ‚Ñ€Ð°Ð½Ñ‹.
        raise HTTPException(status_code=400, detail="bbox Ð²Ð½Ðµ Ñ€Ð°Ð·ÑƒÐ¼Ð½Ð¾Ð³Ð¾ Ñ€Ð°Ð·Ð¼ÐµÑ€Ð° ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°.")
    # Ð¨Ð¸Ñ€Ð¸Ð½Ð° Ð´Ð¾ 640 px; Ð²Ñ‹ÑÐ¾Ñ‚Ð° â€” Ð¸Ð· Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ñ… Ð¿Ñ€Ð¾Ð¿Ð¾Ñ€Ñ†Ð¸Ð¹ bbox, Ñ‡Ñ‚Ð¾Ð±Ñ‹
    # ÑÐ¾Ð²Ð¿Ð°ÑÑ‚ÑŒ Ñ SVG-ÐºÐ¾Ð½Ñ‚ÑƒÑ€Ð¾Ð¼ ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ñ‹.
    width = 640
    height = max(64, min(1280, int(round(width * span_y / span_x))))
    cache_key = f"{round(min_x)}:{round(min_y)}:{round(max_x)}:{round(max_y)}"
    cached = _NSPD_MAP_CACHE.get(cache_key)
    if cached and time.time() - cached[0] < _NSPD_MAP_CACHE_TTL_SECONDS:
        return Response(cached[1], media_type="image/png",
                        headers={"Cache-Control": "public, max-age=3600"})
    try:
        raw = _nspd_wms_map_png(min_x, min_y, max_x, max_y, width, height)
        # ÐÐ¡ÐŸÐ” Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð¿Ñ€Ð¾Ð·Ñ€Ð°Ñ‡Ð½Ñ‹Ð¼ PNG (Ð¿Ñ€Ð¾Ð±Ð°), Ð° Ð¿Ñ€Ð¾Ð·Ñ€Ð°Ñ‡Ð½Ð¾ÑÑ‚ÑŒ Ð´Ð°Ð»ÑŒÑˆÐµ Ð¾Ð¿Ð°ÑÐ½Ð°:
        # Ñ„Ð¾Ñ‚Ð¾ Ð±Ð¾Ñ‚Ð° Ð¿Ñ€Ð¸ ÐºÐ¾Ð½Ð²ÐµÑ€Ñ‚Ð°Ñ†Ð¸Ð¸ Ð² RGB Ð¿Ð¾Ð»ÑƒÑ‡Ð¸Ð»Ð¾ Ð±Ñ‹ Ñ‡Ñ‘Ñ€Ð½Ñ‹Ð¹ Ñ„Ð¾Ð½. ÐŸÐ»Ð¾ÑÐºÐ¾Ðµ
        # ÑÐ²ÐµÑ‚Ð»Ð¾Ðµ Ð¾ÑÐ½Ð¾Ð²Ð°Ð½Ð¸Ðµ ÐºÐ»Ð°Ð´Ñ‘Ñ‚ÑÑ Ð¾Ð´Ð¸Ð½ Ñ€Ð°Ð· Ð·Ð´ÐµÑÑŒ.
        from PIL import Image
        layer = Image.open(io.BytesIO(raw)).convert("RGBA")
        base = Image.new("RGBA", layer.size, (245, 245, 243, 255))
        base.alpha_composite(layer)
        buffer = io.BytesIO()
        base.convert("RGB").save(buffer, format="PNG")
        raw = buffer.getvalue()
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"ÐŸÐ¾Ð´Ð»Ð¾Ð¶ÐºÐ° ÐºÐ°Ñ€Ñ‚Ñ‹ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°: {exc}")
    if len(_NSPD_MAP_CACHE) >= _NSPD_MAP_CACHE_LIMIT:
        _NSPD_MAP_CACHE.pop(next(iter(_NSPD_MAP_CACHE)), None)
    _NSPD_MAP_CACHE[cache_key] = (time.time(), raw)
    return Response(raw, media_type="image/png",
                    headers={"Cache-Control": "public, max-age=3600"})


def _basemap_zoom(min_x: float, max_x: float, min_y: float, max_y: float, width: int) -> int:
    """ÐœÐ°ÑÑˆÑ‚Ð°Ð± Ñ‚Ð°Ð¹Ð»Ð¾Ð² Ð¿Ð¾Ð´ ÑˆÐ¸Ñ€Ð¸Ð½Ñƒ ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¸ â€” Ð¸ Ð¿Ð¾Ð´ Ð±ÑŽÐ´Ð¶ÐµÑ‚ Ð·Ð°Ð¿Ñ€Ð¾ÑÐ¾Ð².

    Ð¡Ð½Ð°Ñ‡Ð°Ð»Ð° Ð±ÐµÑ€Ñ‘Ñ‚ÑÑ Ñ‚Ð¾Ñ‚ Ð¼Ð°ÑÑˆÑ‚Ð°Ð±, Ð¿Ñ€Ð¸ ÐºÐ¾Ñ‚Ð¾Ñ€Ð¾Ð¼ Ñ‚Ð°Ð¹Ð» Ð»Ð¾Ð¶Ð¸Ñ‚ÑÑ Ð¿Ð¸ÐºÑÐµÐ»ÑŒ Ð² Ð¿Ð¸ÐºÑÐµÐ»ÑŒ:
    ÐºÑ€ÑƒÐ¿Ð½ÐµÐµ â€” Ð¼Ñ‹Ð»Ð¾, Ð¼ÐµÐ»ÑŒÑ‡Ðµ â€” Ð»Ð¸ÑˆÐ½Ð¸Ðµ Ð·Ð°Ð¿Ñ€Ð¾ÑÑ‹. ÐŸÐ¾Ñ‚Ð¾Ð¼ Ð¼Ð°ÑÑˆÑ‚Ð°Ð± Ð¿Ð¾Ð½Ð¸Ð¶Ð°ÐµÑ‚ÑÑ, Ð¿Ð¾ÐºÐ°
    ÑÐºÐ»ÐµÐ¹ÐºÐ° Ð½Ðµ Ð²Ð»ÐµÐ·ÐµÑ‚ Ð² Ð±ÑŽÐ´Ð¶ÐµÑ‚: Ñ‡ÑƒÐ¶Ð¾Ð¹ ÑÐµÑ€Ð²Ð¸Ñ Ð½Ðµ Ð´Ð¾Ð»Ð¶ÐµÐ½ Ð¿Ð»Ð°Ñ‚Ð¸Ñ‚ÑŒ Ð·Ð° Ð½Ð°ÑˆÑƒ ÐºÐ°Ñ€Ñ‚Ñƒ
    ÑÐ¾Ñ‚Ð½ÐµÐ¹ Ð¾Ð±Ñ€Ð°Ñ‰ÐµÐ½Ð¸Ð¹.
    """
    world = 2 * 20037508.342789244
    span_x = max(max_x - min_x, 1.0)
    zoom = int(round(math.log2(world / 256.0 / (span_x / max(width, 1)))))
    zoom = max(1, min(18, zoom))
    while zoom > 1:
        scale = world / (256.0 * (1 << zoom))
        tiles = (math.ceil(span_x / scale / 256.0) + 1) * (
            math.ceil(max(max_y - min_y, 1.0) / scale / 256.0) + 1
        )
        if tiles <= _BASEMAP_TILE_BUDGET:
            break
        zoom -= 1
    return zoom


def _osm_tile(zoom: int, x: int, y: int) -> bytes:
    """ÐžÐ´Ð¸Ð½ Ñ‚Ð°Ð¹Ð», Ñ ÐºÑÑˆÐµÐ¼ Ð½Ð° Ð½ÐµÐ´ÐµÐ»ÑŽ: ÐºÐ°Ñ€Ñ‚Ð° ÑƒÐ»Ð¸Ñ† Ð·Ð° Ð½ÐµÐ´ÐµÐ»ÑŽ Ð½Ðµ Ð¼ÐµÐ½ÑÐµÑ‚ÑÑ."""
    key = f"{zoom}/{x}/{y}"
    cached = _OSM_TILE_CACHE.get(key)
    if cached and time.time() - cached[0] < _OSM_TILE_CACHE_TTL_SECONDS:
        return cached[1]
    url = _OSM_TILE_URL.format(z=zoom, x=x, y=y)
    request = urllib.request.Request(url, headers={
        # Ð¢Ð°Ð¹Ð»Ð¾Ð²Ñ‹Ð¹ ÑÐµÑ€Ð²Ð¸Ñ Ñ‚Ñ€ÐµÐ±ÑƒÐµÑ‚, Ñ‡Ñ‚Ð¾Ð±Ñ‹ ÐºÐ»Ð¸ÐµÐ½Ñ‚ Ð½Ð°Ð·Ñ‹Ð²Ð°Ð»ÑÑ: Ð¾Ð±ÐµÐ·Ð»Ð¸Ñ‡ÐµÐ½Ð½Ñ‹Ð¹ Ð·Ð°Ð¿Ñ€Ð¾Ñ
        # Ð¾Ð½ Ð²Ð¿Ñ€Ð°Ð²Ðµ Ð¾Ñ‚ÐºÐ»Ð¾Ð½Ð¸Ñ‚ÑŒ, Ð¸ Ð¿Ñ€Ð°Ð²Ð¸Ð»ÑŒÐ½Ð¾ Ð´ÐµÐ»Ð°ÐµÑ‚.
        "User-Agent": _LAND_LOOKUP_USER_AGENT,
        "Accept": "image/png,image/*;q=0.9",
    })
    with urllib.request.urlopen(request, timeout=_NSPD_TIMEOUT_SECONDS) as response:
        raw = response.read(1024 * 1024)
    if len(_OSM_TILE_CACHE) >= _OSM_TILE_CACHE_LIMIT:
        _OSM_TILE_CACHE.pop(next(iter(_OSM_TILE_CACHE)), None)
    _OSM_TILE_CACHE[key] = (time.time(), raw)
    return raw


def _basemap_png(min_x: float, min_y: float, max_x: float, max_y: float, width: int) -> bytes:
    """Ð¡ÐºÐ»ÐµÐµÐ½Ð½Ð°Ñ ÐºÐ°Ñ€Ñ‚Ð° ÑƒÐ»Ð¸Ñ† Ð¿Ð¾Ð´ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¹ bbox.

    Ð¢Ð°Ð¹Ð»Ñ‹ Ð¿Ñ€Ð¸Ñ…Ð¾Ð´ÑÑ‚ ÐºÑƒÑÐºÐ°Ð¼Ð¸, Ð° ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ðµ Ð½ÑƒÐ¶Ð½Ð° Ð¾Ð´Ð½Ð° ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ° Ð¿Ð¾Ð´ Ñ‚Ð¾Ñ‚ Ð¶Ðµ bbox, Ð²
    ÐºÐ¾Ñ‚Ð¾Ñ€Ð¾Ð¼ Ð¾Ð½Ð° Ñ€Ð¸ÑÑƒÐµÑ‚ Ñ‚Ð¾Ñ‡ÐºÐ¸: Ð¸Ð½Ð°Ñ‡Ðµ ÑÐ¾Ð²Ð¼ÐµÑ‰Ð°Ñ‚ÑŒ Ð¿Ñ€Ð¸ÑˆÐ»Ð¾ÑÑŒ Ð±Ñ‹ Ð² Ð±Ñ€Ð°ÑƒÐ·ÐµÑ€Ðµ, Ð¸ Ð»ÑŽÐ±Ð¾Ðµ
    Ñ€Ð°ÑÑ…Ð¾Ð¶Ð´ÐµÐ½Ð¸Ðµ Ð¾ÐºÑ€ÑƒÐ³Ð»ÐµÐ½Ð¸Ð¹ ÑƒÐ²Ð¾Ð´Ð¸Ð»Ð¾ Ð±Ñ‹ Ð¿Ñ€Ð¾ÐµÐºÑ‚ Ð½Ð° ÑÐ¾ÑÐµÐ´Ð½ÑŽÑŽ ÑƒÐ»Ð¸Ñ†Ñƒ.
    """
    from PIL import Image

    zoom = _basemap_zoom(min_x, max_x, min_y, max_y, width)
    world = 2 * 20037508.342789244
    origin = -20037508.342789244
    scale = world / (256.0 * (1 << zoom))  # Ð¼ÐµÑ‚Ñ€Ð¾Ð² Ð½Ð° Ð¿Ð¸ÐºÑÐµÐ»ÑŒ
    # ÐŸÐ¸ÐºÑÐµÐ»ÑŒ Ð²ÑÐµÐ¹ ÐºÐ°Ñ€Ñ‚Ñ‹ Ð¼Ð¸Ñ€Ð°: y Ñ€Ð°ÑÑ‚Ñ‘Ñ‚ Ð²Ð½Ð¸Ð·, Ð¿Ð¾ÑÑ‚Ð¾Ð¼Ñƒ ÑÐµÐ²ÐµÑ€ â€” ÑÑ‚Ð¾ Ð¼Ð¸Ð½ÑƒÑ.
    def px(x: float) -> float:
        return (x - origin) / scale

    def py(y: float) -> float:
        return (-y - origin) / scale

    left, right = px(min_x), px(max_x)
    top, bottom = py(max_y), py(min_y)
    x0, x1 = int(math.floor(left / 256)), int(math.floor((right - 1e-6) / 256))
    y0, y1 = int(math.floor(top / 256)), int(math.floor((bottom - 1e-6) / 256))
    limit = 1 << zoom
    canvas = Image.new("RGB", ((x1 - x0 + 1) * 256, (y1 - y0 + 1) * 256), (238, 238, 233))
    got = 0
    for tx in range(x0, x1 + 1):
        for ty in range(y0, y1 + 1):
            if not (0 <= ty < limit):
                continue
            try:
                raw = _osm_tile(zoom, tx % limit, ty)
                tile = Image.open(io.BytesIO(raw)).convert("RGB")
            except Exception:
                # ÐžÐ´Ð¸Ð½ Ð½Ðµ Ð¿Ñ€Ð¸ÑˆÐµÐ´ÑˆÐ¸Ð¹ Ñ‚Ð°Ð¹Ð» â€” Ð´Ñ‹Ñ€ÐºÐ° Ð² ÐºÐ°Ñ€Ñ‚Ðµ, Ð° Ð½Ðµ Ð¾Ñ‚ÐºÐ°Ð· Ð¾Ñ‚ ÐºÐ°Ñ€Ñ‚Ñ‹.
                continue
            canvas.paste(tile, ((tx - x0) * 256, (ty - y0) * 256))
            got += 1
    if not got:
        raise RuntimeError("Ð½Ð¸ Ð¾Ð´Ð¸Ð½ Ñ‚Ð°Ð¹Ð» Ð½Ðµ Ð¿Ð¾Ð»ÑƒÑ‡ÐµÐ½")
    crop = canvas.crop((
        int(round(left - x0 * 256)), int(round(top - y0 * 256)),
        int(round(right - x0 * 256)), int(round(bottom - y0 * 256)),
    ))
    # Ð’Ñ‹ÑˆÐµ Ð½Ð°Ñ‚ÑƒÑ€Ð°Ð»ÑŒÐ½Ð¾Ð³Ð¾ Ñ€Ð°Ð·Ð¼ÐµÑ€Ð° Ð½Ðµ Ñ€Ð°ÑÑ‚ÑÐ³Ð¸Ð²Ð°ÐµÐ¼: Ñ‚Ð°Ð¹Ð» Ð¾Ñ‚Ð´Ð°Ð» ÑÑ‚Ð¾Ð»ÑŒÐºÐ¾ Ð¿Ð¸ÐºÑÐµÐ»ÐµÐ¹,
    # ÑÐºÐ¾Ð»ÑŒÐºÐ¾ Ð¾Ñ‚Ð´Ð°Ð», Ð¸ Ñ€Ð°ÑÑ‚ÑÐ½ÑƒÑ‚Ð°Ñ Ð²Ð´Ð²Ð¾Ðµ Ð¿Ð¾Ð´Ð¿Ð¸ÑÑŒ ÑƒÐ»Ð¸Ñ†Ñ‹ Ñ‡Ð¸Ñ‚Ð°ÐµÑ‚ÑÑ Ñ…ÑƒÐ¶Ðµ Ð¼ÐµÐ»ÐºÐ¾Ð¹.
    # Ð¨Ð¸Ñ€Ð¸Ð½Ñƒ ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¸ Ð½Ð° ÑÐºÑ€Ð°Ð½Ðµ Ð´ÐµÑ€Ð¶Ð¸Ñ‚ Ñ€Ð°Ð¼ÐºÐ°, Ð° Ð½Ðµ Ñ€Ð°ÑÑ‚Ñ€.
    width = min(width, crop.width)
    height = max(32, int(round(width * crop.height / max(crop.width, 1))))
    crop = crop.resize((width, height), Image.LANCZOS)
    buffer = io.BytesIO()
    crop.save(buffer, format="PNG")
    return buffer.getvalue()


@app.get("/land/basemap", include_in_schema=False)
def land_basemap(bbox: str = "", width: int = 1024) -> Response:
    """ÐšÐ°Ñ€Ñ‚Ð° ÑƒÐ»Ð¸Ñ† Ð¿Ð¾Ð´ Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¹ bbox â€” Ð¾Ð´Ð½Ð¾Ð¹ ÐºÐ°Ñ€Ñ‚Ð¸Ð½ÐºÐ¾Ð¹.

    Ð¢Ð¾Ñ‚ Ð¶Ðµ Ð´Ð¾Ð³Ð¾Ð²Ð¾Ñ€, Ñ‡Ñ‚Ð¾ Ñƒ /land/map-image: ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° Ð¿ÐµÑ€ÐµÐ´Ð°Ñ‘Ñ‚ bbox, Ð² ÐºÐ¾Ñ‚Ð¾Ñ€Ð¾Ð¼
    ÑÐ°Ð¼Ð° Ñ€Ð¸ÑÑƒÐµÑ‚, Ð¸ Ð¿Ð¾Ð»ÑƒÑ‡Ð°ÐµÑ‚ Ñ€Ð°ÑÑ‚Ñ€ Ñ€Ð¾Ð²Ð½Ð¾ Ð¿Ð¾Ð´ Ð½ÐµÐ³Ð¾. ÐžÑ‚Ð»Ð¸Ñ‡Ð°ÐµÑ‚ÑÑ ÑÐ»Ð¾Ð¹ â€” Ð½Ðµ Ð³Ñ€Ð°Ð½Ð¸Ñ†Ñ‹
    Ð•Ð“Ð Ð, Ð° ÑƒÐ»Ð¸Ñ†Ñ‹, Ð²Ð¾Ð´Ð° Ð¸ Ð½Ð°Ð·Ð²Ð°Ð½Ð¸Ñ: Ð½Ð° Ð¿ÑÑ‚Ð¸ ÐºÐ¸Ð»Ð¾Ð¼ÐµÑ‚Ñ€Ð°Ñ… Ñ€Ñ‹Ð½Ð¾Ñ‡Ð½Ð¾Ð¹ Ð²Ñ‹Ð±Ð¾Ñ€ÐºÐ¸ Ð½ÑƒÐ¶Ð½Ñ‹
    Ð¾Ð½Ð¸, Ð° ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¹ ÑÐ»Ð¾Ð¹ Ð´Ð°Ñ‘Ñ‚ ÐºÐ»ÑƒÐ±Ð¾Ðº Ð±ÐµÐ· Ð¾Ñ€Ð¸ÐµÐ½Ñ‚Ð¸Ñ€Ð¾Ð².

    Ð›ÑŽÐ±Ð¾Ð¹ ÑÐ±Ð¾Ð¹ â€” 502, Ð¸ ÐºÐ°Ñ€Ñ‚Ð° Ð½Ð° ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ðµ Ð·Ð°Ð¼ÐµÐ½ÑÐµÑ‚ÑÑ ÑÑ…ÐµÐ¼Ð¾Ð¹ Ñ ÐºÐ¾Ð»ÑŒÑ†Ð°Ð¼Ð¸
    Ñ€Ð°ÑÑÑ‚Ð¾ÑÐ½Ð¸Ð¹. ÐŸÐ¾Ð´Ð»Ð¾Ð¶ÐºÐ° â€” Ñ‚Ð¾, Ð½Ð° Ñ‡Ñ‘Ð¼ Ñ€Ð¸ÑÑƒÑŽÑ‚, Ð° Ð½Ðµ Ñ‚Ð¾, Ñ‡Ñ‚Ð¾ ÑÑ‡Ð¸Ñ‚Ð°ÑŽÑ‚: Ð±ÐµÐ· Ð½ÐµÑ‘
    Ð¾Ñ‚Ð²ÐµÑ‚ Ð¾ÑÑ‚Ð°Ñ‘Ñ‚ÑÑ Ð²ÐµÑ€Ð½Ñ‹Ð¼, Ð¿Ñ€Ð¾ÑÑ‚Ð¾ Ñ‡Ð¸Ñ‚Ð°ÐµÑ‚ÑÑ Ñ…ÑƒÐ¶Ðµ.
    """
    remote = _core_api_url("/land/basemap")
    if remote:
        # ÐšÐ°Ðº /land/map-image: Ð½Ð° Render Ð²Ð½ÐµÑˆÐ½Ð¸Ðµ ÐºÐ°Ñ€Ñ‚Ñ‹ Ð½Ðµ Ñ…Ð¾Ð´ÑÑ‚, Ð¿ÐµÑ€ÐµÑÑ‹Ð»Ð°ÐµÐ¼.
        try:
            with urllib.request.urlopen(
                    urllib.request.Request(
                        remote + "?" + urllib.parse.urlencode({"bbox": bbox, "width": width}),
                        headers={"Accept": "image/png"}),
                    timeout=_NSPD_TIMEOUT_SECONDS) as response:
                raw = response.read(8 * 1024 * 1024)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"ÐšÐ°Ñ€Ñ‚Ð° Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°: {exc}")
        return Response(raw, media_type="image/png",
                        headers={"Cache-Control": "public, max-age=86400"})
    try:
        parts = [float(value) for value in str(bbox or "").split(",")]
    except ValueError:
        parts = []
    if len(parts) != 4:
        raise HTTPException(status_code=400, detail="bbox: minX,minY,maxX,maxY Ð² Ð¼ÐµÑ‚Ñ€Ð°Ñ… Ð²ÐµÐ±-Ð¼ÐµÑ€ÐºÐ°Ñ‚Ð¾Ñ€Ð°.")
    min_x, min_y, max_x, max_y = parts
    span_x, span_y = max_x - min_x, max_y - min_y
    if not (0 < span_x <= 200000 and 0 < span_y <= 200000):
        raise HTTPException(status_code=400, detail="bbox Ð²Ð½Ðµ Ñ€Ð°Ð·ÑƒÐ¼Ð½Ð¾Ð³Ð¾ Ñ€Ð°Ð·Ð¼ÐµÑ€Ð° Ð²Ñ‹Ð±Ð¾Ñ€ÐºÐ¸.")
    width = max(256, min(1536, int(width)))
    cache_key = f"{round(min_x)}:{round(min_y)}:{round(max_x)}:{round(max_y)}:{width}"
    cached = _BASEMAP_CACHE.get(cache_key)
    if cached and time.time() - cached[0] < _BASEMAP_CACHE_TTL_SECONDS:
        return Response(cached[1], media_type="image/png",
                        headers={"Cache-Control": "public, max-age=86400"})
    try:
        raw = _basemap_png(min_x, min_y, max_x, max_y, width)
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"ÐšÐ°Ñ€Ñ‚Ð° Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð°: {exc}")
    if len(_BASEMAP_CACHE) >= _BASEMAP_CACHE_LIMIT:
        _BASEMAP_CACHE.pop(next(iter(_BASEMAP_CACHE)), None)
    _BASEMAP_CACHE[cache_key] = (time.time(), raw)
    return Response(raw, media_type="image/png",
                    headers={"Cache-Control": "public, max-age=86400"})


@app.get("/land/overlay-probe", include_in_schema=False)
def land_overlay_probe(cad: str = "") -> Response:
    """Ð”Ð¸Ð°Ð³Ð½Ð¾ÑÑ‚Ð¸ÐºÐ° ÑÐ¾Ð²Ð¼ÐµÑ‰ÐµÐ½Ð¸Ñ ÐºÐ¾Ð½Ñ‚ÑƒÑ€Ð° Ð¸ Ð¿Ð¾Ð´Ð»Ð¾Ð¶ÐºÐ¸ Ð¿Ð¾ ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ð¾Ð¼Ñƒ Ð½Ð¾Ð¼ÐµÑ€Ñƒ.

    Ð Ð¸ÑÑƒÐµÑ‚ ÐºÐ¾Ð½Ñ‚ÑƒÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð½Ð° Ñ€Ð°ÑÑ‚Ñ€Ðµ ÐÐ¡ÐŸÐ” Ð¢ÐžÐ™ Ð–Ð• bboxâ†’Ð¿Ð¸ÐºÑÐµÐ»ÑŒ Ð¼Ð°Ñ‚ÐµÐ¼Ð°Ñ‚Ð¸ÐºÐ¾Ð¹, Ñ‡Ñ‚Ð¾
    SVG ÐºÐ°Ñ€Ñ‚Ð¾Ñ‡ÐºÐ¸. Ð›ÑÐ¶ÐµÑ‚ ÐºÐ¾Ð½Ñ‚ÑƒÑ€ Ð½Ð° Ð³Ñ€Ð°Ð½Ð¸Ñ†Ñ‹ Ð¿Ð¾Ð´Ð»Ð¾Ð¶ÐºÐ¸ â€” ÑÐ´Ð²Ð¸Ð³ Ð±Ñ‹Ð» Ð² Ð²Ð¾ÑÐ¿Ñ€Ð¸ÑÑ‚Ð¸Ð¸
    Ð¸Ð»Ð¸ Ð¾Ð±Ð¾Ð±Ñ‰ÐµÐ½Ð¸Ð¸ Ñ€Ð°ÑÑ‚Ñ€Ð°, Ð½Ð°Ñˆ ÐºÐ¾Ð½Ñ‚ÑƒÑ€ Ñ‚Ð¾Ñ‡Ð½ÐµÐµ; ÑƒÐµÐ´ÐµÑ‚ Ð¸ Ð·Ð´ÐµÑÑŒ â€” ÑÐ´Ð²Ð¸Ð³ Ð² Ð´Ð°Ð½Ð½Ñ‹Ñ…, Ð¸
    Ð²Ð¸Ð´ÐµÐ½ ÐµÐ³Ð¾ Ð·Ð½Ð°Ðº. ÐžÑ‚Ð´ÐµÐ»ÑÐµÑ‚ Ð±Ñ€Ð°ÑƒÐ·ÐµÑ€ Ð¾Ñ‚ Ð´Ð°Ð½Ð½Ñ‹Ñ…: ÑÐµÑ€Ð²ÐµÑ€ Ñ€Ð¸ÑÑƒÐµÑ‚ Ð¿Ð¾ Ñ‚Ð¾Ð¹ Ð¶Ðµ
    Ñ„Ð¾Ñ€Ð¼ÑƒÐ»Ðµ, Ñ‡Ñ‚Ð¾ ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð°, Ð¿Ð¾ÑÑ‚Ð¾Ð¼Ñƒ Ñ€Ð°ÑÑ…Ð¾Ð¶Ð´ÐµÐ½Ð¸Ðµ Ñ Ð±Ñ€Ð°ÑƒÐ·ÐµÑ€Ð¾Ð¼ ÑƒÐºÐ°Ð·Ð°Ð»Ð¾ Ð±Ñ‹ Ð½Ð° CSS.
    Ð¡ Render ÐÐ¡ÐŸÐ” Ð·Ð°ÐºÑ€Ñ‹Ñ‚ WAF â€” Ñ„Ð¾Ñ€Ð²Ð°Ñ€Ð´ Ð½Ð° ÑÐ´Ñ€Ð¾. Ð¢Ð¾Ð»ÑŒÐºÐ¾ Ð´Ð¸Ð°Ð³Ð½Ð¾ÑÑ‚Ð¸ÐºÐ°, Ð½Ðµ ÐºÑÑˆÐ¸Ñ€ÑƒÐµÑ‚.
    """
    remote = _core_api_url("/land/overlay-probe")
    if remote:
        try:
            with urllib.request.urlopen(
                    urllib.request.Request(
                        remote + "?" + urllib.parse.urlencode({"cad": cad}),
                        headers={"Accept": "image/png"}),
                    timeout=_NSPD_TIMEOUT_SECONDS + 15) as response:
                raw = response.read(4 * 1024 * 1024)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"Ð¯Ð´Ñ€Ð¾ Ð½ÐµÐ´Ð¾ÑÑ‚ÑƒÐ¿Ð½Ð¾: {exc}")
        return Response(raw, media_type="image/png", headers={"Cache-Control": "no-store"})

    number = _land_text(cad).strip()
    if not number:
        raise HTTPException(status_code=400, detail="cad: ÐºÐ°Ð´Ð°ÑÑ‚Ñ€Ð¾Ð²Ñ‹Ð¹ Ð½Ð¾Ð¼ÐµÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°.")
    features = _nspd_search_features(number)
    geometry = None
    for feature in features:
        options = _nspd_options(feature)
        if _land_text(_nspd_value(options, "cadastral_number")) == number:
            geometry = feature.get("geometry")
            break
    if geometry is None and features:
        geometry = features[0].get("geometry")
    rings = _geometry_contours_merc(geometry) if geometry else []
    if not rings:
        raise HTTPException(status_code=404, detail="ÐšÐ¾Ð½Ñ‚ÑƒÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° Ð½Ðµ Ð¿Ð¾Ð»ÑƒÑ‡ÐµÐ½ Ð¸Ð· Ð•Ð“Ð Ð.")

    xs = [p[0] for ring in rings for p in ring]
    ys = [p[1] for ring in rings for p in ring]
    min_x, max_x, min_y, max_y = min(xs), max(xs), min(ys), max(ys)
    span_x, span_y = max_x - min_x, max_y - min_y
    if not (span_x > 0 and span_y > 0):
        raise HTTPException(status_code=404, detail="Ð’Ñ‹Ñ€Ð¾Ð¶Ð´ÐµÐ½Ð½Ñ‹Ð¹ ÐºÐ¾Ð½Ñ‚ÑƒÑ€ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ°.")
    # Ð¢Ð¾Ñ‚ Ð¶Ðµ pad Ð¸ Ð°ÑÐ¿ÐµÐºÑ‚, Ñ‡Ñ‚Ð¾ landContourSvg + land_map_image: pixel-Ð²-pixel.
    pad = max(span_x, span_y) * 0.06
    w, h = span_x + 2 * pad, span_y + 2 * pad
    width = 640
    height = max(64, min(1280, int(round(width * h / w))))

    from PIL import Image, ImageDraw
    raw = _nspd_wms_map_png(min_x - pad, min_y - pad, max_x + pad, max_y + pad, width, height)
    layer = Image.open(io.BytesIO(raw)).convert("RGBA")
    base = Image.new("RGBA", layer.size, (245, 245, 243, 255))
    base.alpha_composite(layer)
    draw = ImageDraw.Draw(base)
    for ring in rings:
        # ÐžÑ‚Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ðµ Ñ‚Ð¾Ñ‡ÐºÐ¸ Ð² Ð¿Ð¸ÐºÑÐµÐ»ÑŒ ÑÐ¾Ð²Ð¿Ð°Ð´Ð°ÐµÑ‚ Ñ SVG ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ñ‹:
        # x=(X-(minX-pad))/w, y=((maxY+pad)-Y)/h â€” Ñ‚Ð° Ð¶Ðµ Ñ„Ð¾Ñ€Ð¼ÑƒÐ»Ð°, Ñ‡Ñ‚Ð¾ Ð² path.
        pts = [((p[0] - (min_x - pad)) / w * width,
                ((max_y + pad) - p[1]) / h * height) for p in ring]
        if len(pts) >= 2:
            draw.line(pts + [pts[0]], fill=(0, 90, 255, 255), width=3)
    buffer = io.BytesIO()
    base.convert("RGB").save(buffer, format="PNG")
    return Response(buffer.getvalue(), media_type="image/png",
                    headers={"Cache-Control": "no-store"})


def _geocode_yandex(address: str, limit: int) -> list[dict[str, Any]]:
    api_key = _env_str("YANDEX_GEOCODER_API_KEY")
    if not api_key:
        return []
    params = urllib.parse.urlencode({
        "apikey": api_key,
        "format": "json",
        "lang": "ru_RU",
        "results": limit,
        "geocode": address,
    })
    payload = _land_fetch_json(
        f"https://geocode-maps.yandex.ru/1.x/?{params}",
        service="Ð“ÐµÐ¾ÐºÐ¾Ð´ÐµÑ€ Ð¯Ð½Ð´ÐµÐºÑÐ°",
    )
    members = (
        ((payload or {}).get("response") or {}).get("GeoObjectCollection") or {}
    ).get("featureMember") or []
    results: list[dict[str, Any]] = []
    for member in members[:limit]:
        geo_object = (member or {}).get("GeoObject") or {}
        point = _land_text((geo_object.get("Point") or {}).get("pos"))
        chunks = point.split()
        if len(chunks) != 2:
            continue
        lng, lat = _land_float(chunks[0]), _land_float(chunks[1])
        if lat is None or lng is None:
            continue
        meta = (
            (geo_object.get("metaDataProperty") or {}).get("GeocoderMetaData") or {}
        )
        results.append({
            "lat": lat,
            "lng": lng,
            "label": _land_text(meta.get("text")) or _land_text(geo_object.get("name")),
            "provider": "Ð¯Ð½Ð´ÐµÐºÑ",
        })
    return results


def _geocode_dadata(address: str, limit: int) -> list[dict[str, Any]]:
    api_key = _env_str("DADATA_API_KEY")
    if not api_key:
        return []
    payload = _land_fetch_json(
        "https://suggestions.dadata.ru/suggestions/api/4_1/rs/suggest/address",
        service="DaData",
        data=json.dumps({"query": address, "count": limit}, ensure_ascii=False).encode("utf-8"),
        headers={"Authorization": f"Token {api_key}"},
    )
    results: list[dict[str, Any]] = []
    for suggestion in ((payload or {}).get("suggestions") or [])[:limit]:
        data = (suggestion or {}).get("data") or {}
        lat, lng = _land_float(data.get("geo_lat")), _land_float(data.get("geo_lon"))
        if lat is None or lng is None:
            continue
        results.append({
            "lat": lat,
            "lng": lng,
            "label": _land_text(suggestion.get("value")),
            "cadastral_number": _land_text(data.get("cadastral_number") or data.get("house_cadnum")),
            "provider": "DaData",
        })
    return results


def _geocode_nominatim(address: str, limit: int) -> list[dict[str, Any]]:
    global _nominatim_last_call
    with _nominatim_lock:
        # Ð£ÑÐ»Ð¾Ð²Ð¸Ñ OSM: Ð½Ðµ Ñ‡Ð°Ñ‰Ðµ Ð¾Ð´Ð½Ð¾Ð³Ð¾ Ð·Ð°Ð¿Ñ€Ð¾ÑÐ° Ð² ÑÐµÐºÑƒÐ½Ð´Ñƒ.
        wait = 1.0 - (time.time() - _nominatim_last_call)
        if wait > 0:
            time.sleep(min(wait, 1.0))
        _nominatim_last_call = time.time()
    params = urllib.parse.urlencode({
        "q": address,
        "format": "jsonv2",
        "limit": limit,
        "accept-language": "ru",
        "countrycodes": "ru",
    })
    payload = _land_fetch_json(
        f"{_NOMINATIM_BASE_URL}/search?{params}",
        service="Ð“ÐµÐ¾ÐºÐ¾Ð´ÐµÑ€ OpenStreetMap",
    )
    results: list[dict[str, Any]] = []
    for item in (payload or [])[:limit]:
        lat, lng = _land_float((item or {}).get("lat")), _land_float((item or {}).get("lon"))
        if lat is None or lng is None:
            continue
        results.append({
            "lat": lat,
            "lng": lng,
            "label": _land_text(item.get("display_name")),
            "provider": "OpenStreetMap",
        })
    return results


_GEOCODERS = (
    ("yandex", _geocode_yandex),
    ("dadata", _geocode_dadata),
    ("nominatim", _geocode_nominatim),
)


def _geocode_address(address: str, limit: int) -> tuple[list[dict[str, Any]], list[str]]:
    forced = _env_str("LAND_LOOKUP_GEOCODER").lower()
    warnings: list[str] = []
    for name, provider in _GEOCODERS:
        if forced and forced != name:
            continue
        try:
            candidates = provider(address, limit)
        except HTTPException as exc:
            warnings.append(str(exc.detail))
            continue
        if candidates:
            return candidates, warnings
    return [], warnings


def _land_lookup_by_numbers(numbers: list[str]) -> list[dict[str, Any]]:
    if len(numbers) > 1 and _LAND_LOOKUP_WORKERS > 1:
        workers = min(_LAND_LOOKUP_WORKERS, len(numbers))
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            batches = list(pool.map(lambda number: _land_lookup_by_numbers([number]), numbers))
        results = [item for batch in batches for item in batch]
        # Ð’Ñ‚Ð¾Ñ€Ð¾Ð¹ Ð·Ð°Ñ…Ð¾Ð´ Ð¿Ð¾ Ð¿Ñ€Ð¾Ð¼Ð°Ñ…Ð°Ð¼ â€” Ð¿Ð¾ÑÐ»ÐµÐ´Ð¾Ð²Ð°Ñ‚ÐµÐ»ÑŒÐ½Ñ‹Ð¹, Ñ‡Ñ‚Ð¾Ð±Ñ‹ Ð½Ðµ Ð´Ð°Ð²Ð¸Ñ‚ÑŒ Ð½Ð°
        # Ð¿Ð¾Ñ€Ñ‚Ð°Ð»: Ð¿Ñ€Ð¸ Ð¿Ð°Ñ€Ð°Ð»Ð»ÐµÐ»ÑŒÐ½Ð¾Ð¼ Ð¾Ð¿Ñ€Ð¾ÑÐµ ÐÐ¡ÐŸÐ” Ñ‡Ð°ÑÑ‚ÑŒ Ð½Ð¾Ð¼ÐµÑ€Ð¾Ð² Ð¾Ñ‚Ð²ÐµÑ‡Ð°ÐµÑ‚ Ð¿ÑƒÑÑ‚Ð¾,
        # Ð¸ Ð±ÐµÐ· Ð¿Ð¾Ð²Ñ‚Ð¾Ñ€Ð° ÑƒÑ‡Ð°ÑÑ‚Ð¾Ðº Ð²Ñ‹Ð¿Ð°Ð´Ð°Ð» Ð¸Ð· Ñ€Ð°ÑÑ‡Ñ‘Ñ‚Ð° Ð²Ð¼ÐµÑÑ‚Ðµ ÑÐ¾ ÑÐ²Ð¾ÐµÐ¹ Ð¿Ð»Ð¾Ñ‰Ð°Ð´ÑŒÑŽ.
        misses = [item["cadastral_number"] for item in results if not item.get("found")]
        if misses:
            retried = {number: _land_lookup_by_numbers([number])[0] for number in misses}
            results = [
                retried.get(item["cadastral_number"], item)
                if not item.get("found") and retried.get(item["cadastral_number"], {}).get("found")
                else item
                for item in results
            ]
        return results
    results: list[dict[str, Any]] = []
    for number in numbers:
        parts = _cadastral_number_parts(number)
        try:
            features = _nspd_search_features(number)
        except HTTPException as exc:
            results.append({
                "found": False,
                "cadastral_number": number,
                "region": parts["region_hint"],
                "quarter": parts["quarter"],
                "map_url": _nspd_map_url(None, number),
                "note": str(exc.detail),
            })
            continue
        matched = [
            item for item in features
            if _land_text(_nspd_value(_nspd_options(item), "cadastral_number")) == number
        ] or features[:1]
        if not matched:
            results.append({
                "found": False,
                "cadastral_number": number,
                "region": parts["region_hint"],
                "quarter": parts["quarter"],
                "map_url": _nspd_map_url(None, number),
                "note": "Ð’ Ð•Ð“Ð Ð Ð¿Ð¾ ÑÑ‚Ð¾Ð¼Ñƒ Ð½Ð¾Ð¼ÐµÑ€Ñƒ ÑÐ²ÐµÐ´ÐµÐ½Ð¸Ð¹ Ð½Ðµ Ð½Ð°Ð¹Ð´ÐµÐ½Ð¾.",
            })
            continue
        results.append(_normalize_nspd_feature(matched[0]))
    return results


def _land_lookup_features_to_results(
    features: list[dict[str, Any]], limit: int, *, only_land: bool = False
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    """ÐÐ¾Ñ€Ð¼Ð°Ð»Ð¸Ð·Ð¾Ð²Ð°Ð½Ð½Ñ‹Ðµ Ð¾Ð±ÑŠÐµÐºÑ‚Ñ‹ Ð•Ð“Ð Ð Ð¸ ÑÑ‡Ñ‘Ñ‚Ñ‡Ð¸Ðº ÑÐºÑ€Ñ‹Ñ‚Ð¾Ð³Ð¾ Ð¿Ð¾ Ð²Ð¸Ð´Ð°Ð¼."""
    normalized = [_normalize_nspd_feature(item) for item in features]
    hidden: dict[str, int] = {}
    if only_land:
        for item in normalized:
            if item["kind"] != "land":
                hidden[item["kind"]] = hidden.get(item["kind"], 0) + 1
        normalized = [item for item in normalized if item["kind"] == "land"]
    lands = [item for item in normalized if item["kind"] == "land"]
    ordered = lands + [item for item in normalized if item["kind"] != "land"]
    unique: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in ordered:
        key = item["cadastral_number"] or json.dumps(item.get("center") or {}, sort_keys=True)
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)
        if len(unique) >= limit:
            break
    return unique, hidden


