# Ð Ð°ÑÑ‡Ñ‘Ñ‚ ÐŸÐ¾Ð´Ð¼Ð¾ÑÐºÐ¾Ð²ÑŒÑ Ñ‚ÑÐ½ÐµÑ‚ ÑÐ²ÐµÐ´ÐµÐ½Ð¸Ñ Ð•Ð“Ð Ð Ð¸Ð· ÐÐ¡ÐŸÐ”, Ð° Ñ‚ÑƒÐ´Ð° Ð¿ÑƒÑÐºÐ°ÑŽÑ‚ Ð½Ðµ Ð¾Ñ‚Ð¾Ð²ÑÑŽÐ´Ñƒ:
# Ð½Ð° Render Ð·Ð°Ð¿Ñ€Ð¾ÑÑ‹ Ðº nspd.gov.ru Ð½Ðµ Ð¿Ñ€Ð¾Ñ…Ð¾Ð´ÑÑ‚. ÐŸÐ¾ÑÑ‚Ð¾Ð¼Ñƒ Ð±Ð¾Ñ‚ Ð½Ð° Render ÑÑ‡Ð¸Ñ‚Ð°ÐµÑ‚ Ð½Ðµ
# ÑÐ°Ð¼, Ð° Ð¾Ð±Ñ€Ð°Ñ‰Ð°ÐµÑ‚ÑÑ Ðº ÑÐ´Ñ€Ñƒ, Ñ€Ð°Ð·Ð²Ñ‘Ñ€Ð½ÑƒÑ‚Ð¾Ð¼Ñƒ Ñ‚Ð°Ð¼, Ð³Ð´Ðµ ÐÐ¡ÐŸÐ” Ð´Ð¾ÑÑ‚ÑƒÐ¿ÐµÐ½. ÐŸÑƒÑÑ‚Ð¾Ðµ
# Ð·Ð½Ð°Ñ‡ÐµÐ½Ð¸Ðµ Ð¾Ð·Ð½Ð°Ñ‡Ð°ÐµÑ‚ Â«ÑÑ‡Ð¸Ñ‚Ð°Ñ‚ÑŒ Ð½Ð° Ð¼ÐµÑÑ‚ÐµÂ» â€” Ñ‚Ð°Ðº Ñ€Ð°Ð±Ð¾Ñ‚Ð°ÐµÑ‚ ÑÐ°Ð¼Ð¾ ÑÐ´Ñ€Ð¾, Ð¸Ð½Ð°Ñ‡Ðµ Ð¾Ð½Ð¾
# Ð²Ñ‹Ð·Ñ‹Ð²Ð°Ð»Ð¾ Ð±Ñ‹ ÑÐ°Ð¼Ð¾ ÑÐµÐ±Ñ.
_MO_CALC_API_URL = _env_str("MO_CALC_API_URL", "").strip()
# Ð”Ð²Ð°Ð´Ñ†Ð°Ñ‚ÑŒ Ð´Ð²Ð° ÑƒÑ‡Ð°ÑÑ‚ÐºÐ° â€” ÑÑ‚Ð¾ Ð´Ð²Ð°Ð´Ñ†Ð°Ñ‚ÑŒ Ð´Ð²Ð° Ð¾Ð±Ñ€Ð°Ñ‰ÐµÐ½Ð¸Ñ Ðº Ð•Ð“Ð Ð, Ð¼Ð¸Ð½ÑƒÑ‚Ñ‹ Ñ€Ð°Ð±Ð¾Ñ‚Ñ‹.
_MO_CALC_TIMEOUT_SECONDS = max(30.0, _env_float("MO_CALC_TIMEOUT_SECONDS", 180.0))


def _core_api_url(path: str) -> str:
    """ÐÐ´Ñ€ÐµÑ Ð¼ÐµÑ‚Ð¾Ð´Ð° ÑÐ´Ñ€Ð°. Ð‘Ð°Ð·Ñƒ Ð±ÐµÑ€Ñ‘Ð¼ Ð¸Ð· MO_CALC_API_URL, Ñ‡Ñ‚Ð¾Ð±Ñ‹ Ð½Ðµ Ð¿Ð»Ð¾Ð´Ð¸Ñ‚ÑŒ Ð¿ÐµÑ€ÐµÐ¼ÐµÐ½Ð½Ñ‹Ðµ."""
    base = _env_str("CORE_API_URL", "").strip().rstrip("/")
    if not base and _MO_CALC_API_URL:
        base = _MO_CALC_API_URL.rstrip("/")
        if base.endswith("/mo/calculate"):
            base = base[: -len("/mo/calculate")]
    return f"{base}{path}" if base else ""


def _core_post(url: str, payload: dict[str, Any], timeout: float) -> dict[str, Any]:
    """Ð—Ð°Ð¿Ñ€Ð¾Ñ Ðº ÑÐ´Ñ€Ñƒ. Ð¢Ð¸Ñ…Ð¾Ð³Ð¾ Ð¾Ñ‚ÐºÐ°Ñ‚Ð° Ð½Ð° Ð»Ð¾ÐºÐ°Ð»ÑŒÐ½Ñ‹Ð¹ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚ Ð½ÐµÑ‚.

    Ð›Ð¾ÐºÐ°Ð»ÑŒÐ½Ñ‹Ð¹ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚ Ð½Ð° Render Ð´Ð°Ð» Ð±Ñ‹ Ð¿ÑƒÑÑ‚Ð¾Ð¹ Ð•Ð“Ð Ð Ð¸ Ð¼Ð¾Ð»Ñ‡Ð° Ð½ÐµÐ²ÐµÑ€Ð½Ñ‹Ðµ Ð¢Ð­ÐŸ, Ñ‡Ñ‚Ð¾
    Ñ…ÑƒÐ¶Ðµ Ñ‡ÐµÑÑ‚Ð½Ð¾Ð¹ Ð¾ÑˆÐ¸Ð±ÐºÐ¸: Ð¿Ð¾Ð»ÑŒÐ·Ð¾Ð²Ð°Ñ‚ÐµÐ»ÑŒ Ð±Ñ‹ Ð½Ðµ ÑƒÐ·Ð½Ð°Ð», Ñ‡Ñ‚Ð¾ Ñ†Ð¸Ñ„Ñ€Ñ‹ Ð½Ðµ Ñ ÐÐ¡ÐŸÐ”.
    """
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = str((json.loads(exc.read().decode("utf-8")) or {}).get("detail") or "")
        except Exception:
            detail = ""
        raise HTTPException(
            status_code=502,
            detail=detail or f"Ð¯Ð´Ñ€Ð¾ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚Ð° Ð¾Ñ‚Ð²ÐµÑ‚Ð¸Ð»Ð¾ Ð¾ÑˆÐ¸Ð±ÐºÐ¾Ð¹ {exc.code}.",
        ) from exc
    except socket.timeout as exc:
        raise HTTPException(
            status_code=504,
            detail=(
                f"Ð¯Ð´Ñ€Ð¾ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚Ð° Ð½Ðµ Ð¾Ñ‚Ð²ÐµÑ‚Ð¸Ð»Ð¾ Ð·Ð° {int(timeout)} Ñ. "
                "Ð¡Ð²ÐµÐ´ÐµÐ½Ð¸Ñ Ð•Ð“Ð Ð Ð¿Ð¾ Ð±Ð¾Ð»ÑŒÑˆÐ¾Ð¼Ñƒ ÑÐ¿Ð¸ÑÐºÑƒ ÑƒÑ‡Ð°ÑÑ‚ÐºÐ¾Ð² ÑÐ¾Ð±Ð¸Ñ€Ð°ÑŽÑ‚ÑÑ Ð´Ð¾Ð»Ð³Ð¾ â€” Ð¿Ð¾Ð¿Ñ€Ð¾Ð±ÑƒÐ¹Ñ‚Ðµ ÐµÑ‰Ñ‘ Ñ€Ð°Ð·."
            ),
        ) from exc
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"ÐÐµ ÑƒÐ´Ð°Ð»Ð¾ÑÑŒ Ð¾Ð±Ñ€Ð°Ñ‚Ð¸Ñ‚ÑŒÑÑ Ðº ÑÐ´Ñ€Ñƒ Ñ€Ð°ÑÑ‡Ñ‘Ñ‚Ð°: {exc}",
        ) from exc


def _core_forward_payload(req: BaseModel) -> dict[str, Any]:
    """Ð¢ÐµÐ»Ð¾ Ð·Ð°Ð¿Ñ€Ð¾ÑÐ° Ñ†ÐµÐ»Ð¸ÐºÐ¾Ð¼, ÐºÐ°Ðº ÐµÐ³Ð¾ Ð¿Ñ€Ð¸ÑÐ»Ð°Ð» Ð±Ñ€Ð°ÑƒÐ·ÐµÑ€ Ð¸Ð»Ð¸ ÑÐ¾Ð±Ñ€Ð°Ð» Ð±Ð¾Ñ‚."""
    dump = getattr(req, "model_dump", None) or getattr(req, "dict")
